    local lane = extract_int_value(argument)
    lane === nothing && reject!(Internal("$at: Lane index must be an integer literal or constant: $node"), at)
    (lane < 0 || lane >= num_lanes) && reject!(Internal("$at: Lane index, $lane, out of bounds: $node"), at)
    return lane
end

# A call Julia resolved names a method, never one of dart:_wasm's intrinsics; a call of a builtin is
# Julia's own operation: `===` dart's identical, `ifelse` a select, a conversion or a shift its case of
# dart's switch, and any other intrinsic the operator dart intrinsifies on an int, double or bool receiver (dart's
# generateInstanceIntrinsic, :985): a binary one through the binary operator map, a unary one through
# the unary map. An 8- or 16-bit integer, an i32 in its type's form, is read in its operation's
# view and its result put back in that form; Bool's bitwise operations and equality need neither. No arm is null, as dart's.
# a foreign call of libjulia's own function (nir_libjulia_func), lowered inline as Julia's emit_ccall
# lowers its special functions, keyed by name (julia/src/ccall.cpp:1464 is_libjulia_func), where dart
# intrinsifies a static call by its target: Julia's differs in that a foreign call names a C function,
# no member. jl_get_tls_world_age reads the task's world age (ccall.cpp:1717), which in a compiled image
# is the world its code was inferred in (julia/src/jlapi.c:316, julia/src/codegen.cpp:7190
# emit_abi_call), the closed world's (NirWorld's world), an i64 constant; emit_ccall's asserts (a UInt
# result, C's convention, no argument) reject, located. Any other foreign call is no intrinsic, nothing
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, node::NirForeignCall)::Union{WasmBuilder.IR.ValueType,Nothing}
    local libjulia = nir_libjulia_func(node)
    libjulia === :jl_get_tls_world_age || return nothing
    local at = "$(julia_text(self.code_gen.enclosing_member))"
    local rt, cc = node.args[2], node.args[5]
    rt isa NirConst && rt.c.val === UInt ||
        reject!(Internal("julia/src/ccall.cpp:1717 emit_ccall: jl_get_tls_world_age declared to return $rt, not UInt"), at)
    local conv = cc isa NirConst ? (cc.c.val isa Tuple ? cc.c.val[1] : cc.c.val) : nothing
    conv === :ccall || conv === :cdecl ||
        reject!(Internal("julia/src/ccall.cpp:1717 emit_ccall: jl_get_tls_world_age called by the convention $(repr(conv)), not C's"), at)
    isempty(nir_foreign_operands(node)) ||
        reject!(Internal("julia/src/ccall.cpp:1717 emit_ccall: jl_get_tls_world_age takes no argument"), at)
    WasmBuilder.i64_const(b(self), reinterpret(Int64, UInt64(translator(self).component.world)))
    return WasmBuilder.IR.NumType_i64
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, node::Union{NirCall,NirInvoke})::Union{WasmBuilder.IR.ValueType,Nothing}
    if node isa NirInvoke
        local target = nir_invoke_target(node)
        local string_op = generate_static_intrinsic(Val(:string_data_op), target)
        string_op === nothing || return generate_static_intrinsic(self, Val(:string_data), string_op, node.args[2:end])
        target.def in methods(wasm_egal) && return generate_static_intrinsic(self, Val(:egal), node.args[2:end])
        local array_op = generate_static_intrinsic(Val(:wasm_array_op), target)
        array_op === nothing || return generate_static_intrinsic(self, Val(:wasm_array), array_op, target, node.args[2:end])
        local memory_op = generate_static_intrinsic(Val(:memory_data_op), target)
        memory_op === nothing || return generate_static_intrinsic(self, Val(:memory_data), memory_op, target, node.args[2:end])
        local getter = generate_static_getter_intrinsic(self, target)
        getter === nothing || return getter
        target.def.module === Runtime && target.def in methods(Runtime._InterfaceType_class_id) &&
            return generate_static_intrinsic(self, Val(:interface_type_class_id), node.args[2:end])
        target.def.name === :jl_to_typeof && target.def in methods(jl_to_typeof) &&
            return generate_static_intrinsic(self, Val(:to_typeof), node.args[2:end])
        target.def.name === :jl_typetagis && target.def in methods(jl_typetagis) &&
            return generate_static_intrinsic(self, Val(:typetagis), target, node.args[2:end])
        target.def.name === :jl_is_tuple_type && target.def in methods(jl_is_tuple_type) &&
            return generate_static_intrinsic(self, Val(:is_tuple_type), node.args[2:end])
        target.def.name === :jl_is_type_type && target.def in methods(jl_is_type_type) &&
            return generate_static_intrinsic(self, Val(:is_type_type), node.args[2:end])
        target.def.module === Runtime && target.def in methods(Runtime.Record__check_record_type) &&
            return generate_static_intrinsic(self, Val(:check_record_type), node.args[2:end])
        local intrinsic = StaticIntrinsic_from_procedure(target)
        intrinsic === nothing && return nothing
        intrinsic === StaticIntrinsic_getID && return generate_static_intrinsic(self, Val(:get_id), node.args[2:end])
        intrinsic === StaticIntrinsic_isRecordClassId && return generate_static_intrinsic(self, Val(:is_record_class_id), node.args[2:end])
        intrinsic === StaticIntrinsic_unsafeCast && return generate_static_intrinsic(self, Val(:unsafe_cast), node.args[2:end])
        reject!(Unported("dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic"), "the static intrinsic $intrinsic")
    end
    local f = nir_callee(node)
    local args = node.args[2:end]
    # each family of arms is its own method, compiled only when a program reaches it, and inferred and
    # compiled once for every builtin it matches (@nospecialize f with @nospecializeinfer, as Julia's compiler
    # writes a function over any lattice element: Compiler/src/typelattice.jl:210 assert_nested_slotwrapper,
    # :218 widenslotwrapper, Compiler/src/abstractinterpretation.jl:3904 widenreturn): the `f === ...` tests
    # above narrowed f to each builtin's own type, so the memory family alone was compiled ten times
    f === Core.:(===) && length(args) == 2 && return generate_static_intrinsic(self, Val(:identical), f, args)
    f === Core._svec_len && length(args) == 1 && return generate_static_intrinsic(self, Val(:svec_len), f, args)
    f === Core.throw_methoderror && length(args) >= 1 && return generate_static_intrinsic(self, Val(:throw_methoderror), f, args)
    f === Core.nfields && length(args) == 1 && return generate_static_intrinsic(self, Val(:nfields), f, args)
    f === Core.sizeof && length(args) == 1 && return generate_static_intrinsic(self, Val(:sizeof), f, args)
    f === Core.fieldtype && length(args) in (2, 3) && return generate_static_intrinsic(self, Val(:fieldtype), f, args)
    f === Core._svec_ref && length(args) == 2 && return generate_static_intrinsic(self, Val(:svec_ref), f, args)
    f === Core.svec && return generate_static_intrinsic(self, Val(:svec), f, args)
    f === Core._expr && length(args) >= 1 && return generate_static_intrinsic(self, Val(:expr), f, args)
    (f === Core.memorynew || f === Core.memoryrefnew || f === Core.memoryrefget || f === Core.memoryrefset! ||
     f === Core.memoryrefoffset || f === Core.memoryref_isassigned || f === Core.memoryrefswap! ||
     f === Core.memoryrefreplace! || f === Core.memoryrefsetonce! || f === Core.memoryrefmodify!) &&
        return generate_static_intrinsic(self, Val(:memory), f, args)
    f === Core.isdefined && length(args) in (2, 3) && return generate_static_intrinsic(self, Val(:isdefined), f, args)
    # typeof of a value only run time knows: Julia's jl_typeof, a read of the value's tag
    f === Core.typeof && length(args) == 1 && return generate_static_intrinsic(self, Val(:to_typeof), args; tag_of_value = true)
    f === Core.apply_type && return generate_static_intrinsic(self, Val(:run_time_type), f, args)
    f === Core.ifelse && length(args) == 3 && return generate_static_intrinsic(self, Val(:ifelse), f, args)
    f === Core.donotdelete && return generate_static_intrinsic(self, Val(:donotdelete), f, args)
    f isa Core.IntrinsicFunction || return nothing
    # an operation on a 128-bit integer, an operand's or a conversion's result: its two i64 halves
    local converted = length(args) == 2 ? dart_type_of(self, args[1]) : nothing
    (any(a -> type_expand_integer(dart_type_of(self, a)), args) ||
     converted isa DataType && converted <: Type && length(converted.parameters) == 1 && converted.parameters[1] isa Type && type_expand_integer(converted.parameters[1])) &&
        return generate_static_intrinsic(self, Val(:int128), f, args)
    local type_operand = length(args) == 2 ? dart_type_of(self, args[1]) : nothing
    type_operand isa DataType && type_operand <: Type && length(type_operand.parameters) == 1 && type_operand.parameters[1] isa Type &&
        return generate_static_intrinsic(self, Val(:conversion), f, args)
    f === Core.Intrinsics.flipsign_int && length(args) == 2 && return generate_static_intrinsic(self, Val(:flipsign), f, args)
    f === Core.Intrinsics.have_fma && length(args) == 1 && return generate_static_intrinsic(self, Val(:have_fma), f, args)
    f === Core.Intrinsics.fpiseq && length(args) == 2 && return generate_static_intrinsic(self, Val(:fpiseq), f, args)
    length(args) == 2 && (f === Core.Intrinsics.shl_int || f === Core.Intrinsics.lshr_int || f === Core.Intrinsics.ashr_int) &&
        return generate_static_intrinsic(self, Val(:shift), f, args)
    length(args) == 2 && (f === Core.Intrinsics.checked_sdiv_int || f === Core.Intrinsics.checked_srem_int ||
                          f === Core.Intrinsics.checked_udiv_int || f === Core.Intrinsics.checked_urem_int) &&
        return generate_static_intrinsic(self, Val(:checked_division), f, args)
    length(args) == 2 && (f === Core.Intrinsics.checked_smul_int || f === Core.Intrinsics.checked_umul_int) &&
        return generate_static_intrinsic(self, Val(:checked_multiplication), f, args)
    local narrow(t::Type) = generate_static_intrinsic(Val(:narrow), t)
    all(a -> narrow(dart_type_of(self, a)), args) && allequal(dart_type_of(self, a) for a in args) && 1 <= length(args) <= 2 &&
        return generate_static_intrinsic(self, Val(:narrow_operator), f, args)
    return generate_static_intrinsic(self, Val(:operator), f, args)
end

# Julia's integer forms, which the arms share: a type held in its wasm number type at its own width
# (Int32 and UInt32 in an i32, Int64 and UInt64 in an i64, Float32 in an f32, Float64 in an f64)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:full}, t::Type, w::WasmBuilder.IR.ValueType)::Bool =
    t isa DataType && isprimitivetype(t) && w isa WasmBuilder.IR.NumType && 8 * sizeof(t) == 8 * WasmBuilder.byte_size(w)

# An integer held in a register wider than its own bits, which LLVM's type legalizer promotes
# (TypePromoteInteger, src/llvm/legalize_integer_types.jl): an 8- or 16-bit integer is an i32 held as
# Julia's ABI holds it (Translator.translateType), sign-extended for a signed type, zero-extended for
# an unsigned one; a primitive type of its own width with no builtin type (`primitive type P 24`) is
# held in the register LLVM promotes its integer to (src/julia/classes.jl type_promote_integer, an i32
# or an i64), its bits above its own undefined, the promoted value's (GetPromotedInteger). An operation
# reads the operand in the view it needs (a signed comparison, division or arithmetic shift the
# sign-extended bits, an unsigned one the zero-extended bits: SExtPromotedInteger and
# ZExtPromotedInteger, the extensions within the register) and puts a result back in its type's form,
# as Julia's codegen computes at the type's own width (an i8, i16 or i24 in LLVM); a promoted
# primitive's result keeps no form, LLVM's promoted result.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:narrow}, t::Type)::Bool =
    t isa DataType && (t <: Base.BitInteger && sizeof(t) < 4 || generate_static_intrinsic(Val(:promoted), t))

# a primitive type with no builtin type held in a register wider than its own bits (type_promote_integer)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:promoted}, t::Type)::Bool =
    t isa DataType && t !== Bool && !(t <: Base.BitInteger) && (local r = type_promote_integer(t); r !== nothing && sizeof(t) < sizeof(r))

# a narrow integer's register: a promoted primitive's the one LLVM promotes it to, an 8- or 16-bit integer's the i32
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:register}, t::Type)::WasmBuilder.IR.NumType =
    generate_static_intrinsic(Val(:promoted), t) && type_promote_integer(t) === UInt64 ? WasmBuilder.IR.NumType_i64 : WasmBuilder.IR.NumType_i32

# the form a narrow integer is held in: sign-extended (:sext), zero-extended (:zext), or a promoted
# primitive's any-extended register (:any)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:form}, t::Type)::Symbol =
    generate_static_intrinsic(Val(:promoted), t) ? :any : t <: Signed ? :sext : :zext

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(::Val{:put_form}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing
    local form = generate_static_intrinsic(Val(:form), t)
    form === :sext && LLVM.promote_int_op_sign_extend(b, generate_static_intrinsic(Val(:register), t), 8 * sizeof(t))
    form === :zext && LLVM.promote_int_op_zero_extend(b, generate_static_intrinsic(Val(:register), t), 8 * sizeof(t))
    return nothing
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(::Val{:signed_view}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing
    generate_static_intrinsic(Val(:form), t) === :sext || LLVM.promote_int_op_sign_extend(b, generate_static_intrinsic(Val(:register), t), 8 * sizeof(t))
    return nothing
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(::Val{:unsigned_view}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing
    generate_static_intrinsic(Val(:form), t) === :zext || LLVM.promote_int_op_zero_extend(b, generate_static_intrinsic(Val(:register), t), 8 * sizeof(t))
    return nothing
end

# the view an equality compare reads (LegalizeIntegerTypes.cpp:2338 SExtOrZExtPromotedOperands, which
# PromoteSetCCOperands takes for an equality and an unsigned compare): a sign-extended value as it is
# (ComputeMaxSignificantBits no more than its type's width), a zero-extended one as it is too, where LLVM
# writes the zext_inreg that DAGCombine folds away against its known zero bits (no instruction remains),
# and an any-extended one zero-extended, as wasm prefers (its isSExtCheaperThanZExt the default, false)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(::Val{:extended_view}, b::WasmBuilder.InstructionsBuilder, t::Type)::Nothing
    generate_static_intrinsic(Val(:form), t) === :any && LLVM.promote_int_op_zero_extend(b, generate_static_intrinsic(Val(:register), t), 8 * sizeof(t))
    return nothing
end

# a String's data operations (src/julia/wasm_array.jl), the calls dart's String patches make on a
# String's `_data`: each reads the field (an InstanceGet of the String class's `_data`, its
# ClassField) and applies the WasmArray operation, one instruction as dart's intrinsifier emits it:
# WasmArrayRef.length (intrinsics.dart:626, array.len), I8ArrayExt.readUnsigned (:1351, array.get_u),
# I8ArrayExt.write (:1372, array.set), the WasmArray constructor (:1959, array.new_default, here inside the String's struct, its header
# first) and WasmArrayExt.copy (:1254, array.copy). An Int offset or length is wrapped to the i32 a
# wasm array takes, as dart wraps its int.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:string_data_op}, target::Core.MethodInstance)::Union{Symbol,Nothing} =
    target.def in methods(wasm_string_length) ? :length : target.def in methods(wasm_string_codeunit) ? :codeunit :
    target.def in methods(wasm_string_write!) ? :write : target.def in methods(wasm_string_alloc) ? :alloc : target.def in methods(wasm_string_copy!) ? :copy :
    target.def in methods(wasm_string_memory) ? :memory : target.def in methods(wasm_memory_string) ? :string : nothing

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:string_data}, op::Symbol, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32, i64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64
    local at = "$(julia_text(code_gen.enclosing_member)): a String's data"
    local info = get(t.class_info, String, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a String's data operation where String has no class info"), at)
    # the String's one field, its data array (src/julia/classes.jl), read and built by every operation
    local sdata = only(class_instance_fields(String, at))
    local data_index = t.field_index[sdata]
    local array_type = array_type_for_dart_type(t, WasmI8; mutable_ = true)
    local data_of(s::NirValue) = (translate_expression(code_gen, s, info.non_nullable_type); WasmBuilder.struct_get(b, info.struct_, data_index))
    local offset(v::NirValue) = (translate_expression(code_gen, v, i64); WasmBuilder.i32_wrap_i64(b))
    if op === :length
        data_of(args[1])
        WasmBuilder.array_len(b)
        WasmBuilder.i64_extend_i32_u(b)
        return i64
    elseif op === :codeunit
        data_of(args[1])
        offset(args[2])
        WasmBuilder.array_get_u(b, array_type)
        return i32
    elseif op === :write
        # the byte a UInt8 is, an i32 already in its form (translateType), so dart's wrap of its int
        # value to the i32 an i8 array takes has nothing to wrap
        data_of(args[1])
        offset(args[2])
        translate_expression(code_gen, args[3], i32)
        WasmBuilder.array_set(b, array_type)
        # dart's void intrinsics leave the null of the top type (I8ArrayExt.write), Julia's nothing
        WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
        return t.top_type[]
    elseif op === :alloc
        generate_static_intrinsic(self, Val(:new_struct), info, Dict{String,ClassField}(sdata.name => sdata), Dict{String,Function}(
            sdata.name => () -> (offset(args[1]); WasmBuilder.array_new_default(b, array_type))))
        return info.non_nullable_type
    elseif op === :copy
        data_of(args[1])
        offset(args[2])
        data_of(args[3])
        offset(args[4])
        offset(args[5])
        WasmBuilder.array_copy(b, array_type, array_type)
        # dart's void intrinsics leave the null of the top type (WasmArrayExt.[]=), Julia's nothing
        WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
        return t.top_type[]
    elseif op === :memory || op === :string
        # a byte Memory's struct (src/julia/classes.jl _memory_instance_fields: its data array, the
        # String's own array type, and its length), the String's data shared by both
        local minfo = get(t.class_info, Memory{UInt8}, nothing)
        minfo === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a String's Memory where Memory{UInt8} has no class info"), at)
        local mfields = class_instance_fields(Memory{UInt8}, at)
        local mdata = only(f for f in mfields if f.name == "data")
        local mlength = only(f for f in mfields if f.name == "length")
        length(mfields) == 2 || reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: Memory{UInt8} holds $(length(mfields)) fields, not its data and length"), at)
        local data_ref = WasmBuilder.IR.RefType_def(array_type; nullable = false)
        WasmBuilder.unpacked(minfo.struct_.fields[t.field_index[mdata] + 1].type) == data_ref ||
            reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: Memory{UInt8}'s data is no String's data array"), at)
        local p = add_local(code_gen, data_ref)
        if op === :memory
            local mfs = Dict{String,ClassField}(f.name => f for f in mfields)
            # jl_string_to_genericmemory: the String's array, its length the Memory's
            data_of(args[1])
            WasmBuilder.local_set(b, p)
            generate_static_intrinsic(self, Val(:new_struct), minfo, mfs, Dict{String,Function}(
                mdata.name => () -> WasmBuilder.local_get(b, p),
                mlength.name => () -> (WasmBuilder.local_get(b, p); WasmBuilder.array_len(b); WasmBuilder.i64_extend_i32_u(b))))
            return minfo.non_nullable_type
        end
        # jl_genericmemory_to_string: the Memory's array where the String takes all of it, else a copy
        # of its first n bytes
        local k = add_local(code_gen, WasmBuilder.IR.NumType_i32)
        local q = add_local(code_gen, data_ref)
        translate_expression(code_gen, args[1], minfo.non_nullable_type)
        WasmBuilder.struct_get(b, minfo.struct_, t.field_index[mdata])
        WasmBuilder.local_set(b, p)
        offset(args[2])
        WasmBuilder.local_set(b, k)
        generate_static_intrinsic(self, Val(:new_struct), info, Dict{String,ClassField}(sdata.name => sdata), Dict{String,Function}(sdata.name => () -> begin
            WasmBuilder.local_get(b, k)
            WasmBuilder.local_get(b, p)
            WasmBuilder.array_len(b)
            WasmBuilder.i32_eq(b)
            WasmBuilder.if_(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[data_ref])
            WasmBuilder.local_get(b, p)
            WasmBuilder.else_(b)
            WasmBuilder.local_get(b, k)
            WasmBuilder.array_new_default(b, array_type)
            WasmBuilder.local_tee(b, q)
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.local_get(b, p)
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.local_get(b, k)
            WasmBuilder.array_copy(b, array_type, array_type)
            WasmBuilder.local_get(b, q)
            WasmBuilder.var"end"(b)
        end))
        return info.non_nullable_type
    end
    reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a String data operation $op"), at)
end

# Julia's `svec(xs...)`: a new SimpleVector of its operands, jl_svec's, built as dart builds an
# ImmutableWasmArray from its elements (WasmArray.literal, intrinsics.dart:2839: each element
# translated to the array's element type, then array.new_fixed of their count), the array then the
# data field of the SimpleVector's struct below its header (src/julia/classes.jl
# `_svec_instance_fields`), as visitStringConstant wraps a String's bytes
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:svec}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local at = "$(julia_text(code_gen.enclosing_member)): a SimpleVector made"
    local sv_info = get(t.class_info, Core.SimpleVector, nothing)
    sv_info === nothing && reject!(Internal("dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic: Core.SimpleVector has no class info"), at)
    local data = only(class_instance_fields(Core.SimpleVector, at))
    local array_type = (translate_type_of_field(t, data)::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
    local element_type = WasmBuilder.unpacked(array_type.element_type[].type)
    local b = code_gen.b[]
    generate_static_intrinsic(self, Val(:new_struct), sv_info, Dict{String,ClassField}(data.name => data), Dict{String,Function}(data.name => () -> begin
        for element in args
            translate_expression(code_gen, element, element_type)
        end
        WasmBuilder.array_new_fixed(b, array_type, length(args))
    end))
    return WasmBuilder.with_nullability(repr(sv_info), false)
end

# the arms' shared pieces over a class's layout: a class's info and its fields by name; one field of
# them; a memory's class, its data array type and its set flags (`data#isSet`) where it has them; and
# a new struct of a class, its header then each field's value in the class's field order, its class
# recorded allocated as every allocation site records it (dart's recordClassAllocation, functions.dart:446)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:fields_of}, T::Type, at::String)::Tuple{ClassInfo,Dict{String,ClassField}}
    local info = get(translator(self).class_info, T, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: $T has no class info"), at)
    return (info, Dict{String,ClassField}(fld.name => fld for fld in class_instance_fields(T, at)))
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:field}, fs::Dict{String,ClassField}, name::String, at::String)::ClassField = get(fs, name, nothing) === nothing ?
    reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: no field $name in $(collect(keys(fs)))"), at) : fs[name]

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:memory_of}, M::Type, atomic_gap::Function, at::String)::Tuple
    local t = translator(self)
    (M isa DataType && M <: GenericMemory && M.parameters[1] === :not_atomic) || atomic_gap()
    local info, fs = generate_static_intrinsic(self, Val(:fields_of), M, at)
    local data = generate_static_intrinsic(Val(:field), fs, "data", at)
    local array_type = (translate_type_of_field(t, data)::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
    # a reference element admitting nothing: WasmTarget's nothing is the null reference, so #undef
    # is dart's late lowering's set flag (useIsSetField, late_lowering.dart:560), the class's
    # `data#isSet` array, which the layout gives exactly such elements (classes.jl _needs_is_set)
    local is_set = get(fs, "data#isSet", nothing)
    local flag_type = is_set === nothing ? nothing :
        (translate_type_of_field(t, is_set)::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
    return (info, fs, data, array_type, is_set, flag_type)
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:new_struct}, info::ClassInfo, fs::Dict{String,ClassField}, vals::Dict{String,Function})::Nothing
    local t = translator(self)
    local b = self.code_gen.b[]
    # a primitive class's struct is a box's, its class id alone ahead of its value (a 128-bit integer's
    # two halves), as dart's boxing sites push it inline (translator.dart:1642 convertType,
    # constants.dart:854); any other class's header is pushObjectHeaderFields
    info.cls isa DataType && isprimitivetype(info.cls) ? WasmBuilder.i32_const(b, class_id(info)) : push_object_header_fields(b, t, info)
    for fld in sort(collect(values(fs)); by = (x::ClassField) -> t.field_index[x])
        vals[fld.name]()
    end
    WasmBuilder.struct_new(b, info.struct_)
    record_class_allocation(t.functions[], class_id(info))
    return nothing
end

# Julia's `_expr(head, args...)`, the builtin `Expr(...)` calls: jl_f__expr (julia/src/builtins.c:1670)
# takes its head, a Symbol (JL_TYPECHK), allocates a Vector{Any} of the other operands (jl_alloc_vec_any,
# array.c:177: jl_alloc_array_1d, array.c:147, its memory _new_genericmemory_'s, genericmemory.c:56, the
# type's one empty instance for no element, its reference at the memory's first element, the index 0 in
# WasmTarget's MemoryRef, and its size (n,), _new_array, array.c:59), stores each operand (jl_array_ptr_set) and allocates the Expr of the head and
# that vector. Each struct is built by the arms' shared new_struct, each element translated
# to the memory's element type and the elements made by array.new_fixed, as the svec arm builds its data;
# every element written, its set flag set (the memory arm's `data#isSet`, late_lowering's isSet). A head
# Julia did not infer a Symbol is JL_TYPECHK's TypeError, a gap, located
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:expr}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's _expr"
    dart_type_of(self, args[1]) <: Symbol ||
        reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: _expr of a head of type $(dart_type_of(self, args[1])), whose check is jl_f__expr's TypeError (JL_TYPECHK)"), at)
    local n = length(args) - 1
    local new_struct(T::DataType, vals::Dict{String,Function}) = begin
        local info, fs = generate_static_intrinsic(self, Val(:fields_of), T, at)
        sort(collect(keys(fs))) == sort(collect(keys(vals))) ||
            reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: $T holds the fields $(sort(collect(keys(fs)))), not $(sort(collect(keys(vals))))"), at)
        generate_static_intrinsic(self, Val(:new_struct), info, fs, vals)
        WasmBuilder.with_nullability(repr(info), false)
    end
    local M = Memory{Any}
    local minfo, mfs, _, array_type, is_set, flag_type = generate_static_intrinsic(self, Val(:memory_of), M,
        () -> reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: $M is no memory of :not_atomic"), at), at)
    local mem = add_local(code_gen, WasmBuilder.with_nullability(repr(minfo), false))
    if n == 0
        # _new_genericmemory_'s zero-sized allocation: the type's one empty instance
        instantiate_constant(code_gen, NirConst(Core.Const(M.instance)), mem.type)
    else
        local element = WasmBuilder.unpacked(array_type.element_type[].type)
        local vals = Dict{String,Function}(
            "data" => () -> (foreach((a::NirValue) -> translate_expression(code_gen, a, element), args[2:end]); WasmBuilder.array_new_fixed(b, array_type, n)),
            "length" => () -> WasmBuilder.i64_const(b, n))
        # every element written, its set flag set (the memory arm's memoryrefset!)
        is_set === nothing || (vals["data#isSet"] = () -> (WasmBuilder.i32_const(b, 1); WasmBuilder.i32_const(b, n); WasmBuilder.array_new(b, something(flag_type))))
        new_struct(M, vals)
    end
    WasmBuilder.local_set(b, mem)
    local ref = add_local(code_gen, new_struct(MemoryRef{Any}, Dict{String,Function}(
        "ptr_or_offset" => () -> WasmBuilder.i64_const(b, 0), "mem" => () -> WasmBuilder.local_get(b, mem))))
    WasmBuilder.local_set(b, ref)
    local ainfo, afs = generate_static_intrinsic(self, Val(:fields_of), Vector{Any}, at)
    local size_type = WasmBuilder.unpacked(ainfo.struct_.fields[translator(self).field_index[generate_static_intrinsic(Val(:field), afs, "size", at)] + 1].type)
    local vec = add_local(code_gen, new_struct(Vector{Any}, Dict{String,Function}(
        "ref" => () -> WasmBuilder.local_get(b, ref),
        "size" => () -> instantiate_constant(code_gen, NirConst(Core.Const((n,))), size_type))))
    WasmBuilder.local_set(b, vec)
    local einfo, efs = generate_static_intrinsic(self, Val(:fields_of), Expr, at)
    local head_type = WasmBuilder.unpacked(einfo.struct_.fields[translator(self).field_index[generate_static_intrinsic(Val(:field), efs, "head", at)] + 1].type)
    return new_struct(Expr, Dict{String,Function}(
        "head" => () -> translate_expression(code_gen, args[1], head_type),
        "args" => () -> WasmBuilder.local_get(b, vec)))
end

# dart:_wasm's operations on a mutable wasm array Julia code holds (src/julia/wasm_array.jl): the
# WasmArray constructor (intrinsics.dart:1959, array.new_default), WasmArray.write (:1290, array.set,
# a packed element truncated) and WasmArrayRef.length (:626, array.len), each one instruction as
# dart's intrinsifier emits it. The array type is the element type's (arrayTypeForDartType, mutable);
# an Int offset or length is wrapped to the i32 a wasm array takes, as dart wraps its int.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:wasm_array_op}, target::Core.MethodInstance)::Union{Symbol,Nothing} =
    target.def in methods(wasm_array_new) ? :new : target.def in methods(wasm_array_write!) ? :write :
    target.def in methods(wasm_array_length) ? :length : target.def in methods(wasm_array_read) ? :read :
    target.def in methods(wasm_array_read_unsigned) ? :read_unsigned : nothing

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:wasm_array}, op::Symbol, target::Core.MethodInstance, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32, i64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64
    local at = "$(julia_text(code_gen.enclosing_member)): a wasm array"
    local params = Base.unwrap_unionall(target.specTypes).parameters
    # the array's type: WasmArray{T}, the constructor's type argument or the receiver's type
    local array_class = op === :new ? params[2].parameters[1] : params[2]
    array_class isa DataType && array_class <: WasmArray && array_class.parameters[1] isa Type ||
        reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a wasm array operation on $(array_class)"), at)
    local array_type = array_type_for_dart_type(t, array_class.parameters[1]; mutable_ = true)
    local array_ref = WasmBuilder.IR.RefType_def(array_type; nullable = false)
    local offset(v::NirValue) = (translate_expression(code_gen, v, i64); WasmBuilder.i32_wrap_i64(b))
    if op === :new
        offset(args[2])
        WasmBuilder.array_new_default(b, array_type)
        return array_ref
    elseif op === :write
        translate_expression(code_gen, args[1], array_ref)
        offset(args[2])
        translate_expression(code_gen, args[3], WasmBuilder.unpacked(array_type.element_type[].type))
        WasmBuilder.array_set(b, array_type)
        # dart's void intrinsics leave the null of the top type (WasmArrayExt.[]=), Julia's nothing
        WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
        return t.top_type[]
    elseif op === :length
        translate_expression(code_gen, args[1], array_ref)
        WasmBuilder.array_len(b)
        WasmBuilder.i64_extend_i32_u(b)
        return i64
    elseif op === :read
        # WasmArrayExt.[] (intrinsics.dart:1223): array.get at the index wrapped to i32
        translate_expression(code_gen, args[1], array_ref)
        offset(args[2])
        WasmBuilder.array_get(b, array_type)
        return WasmBuilder.unpacked(array_type.element_type[].type)
    elseif op === :read_unsigned
        # readUnsigned (intrinsics.dart:1351): array.get_u, zero-extended to dart's int
        translate_expression(code_gen, args[1], array_ref)
        offset(args[2])
        WasmBuilder.array_get_u(b, array_type)
        WasmBuilder.i64_extend_i32_u(b)
        return i64
    end
    reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a wasm array operation $op"), at)
end

# jl_typetagis (julia.h:136, src/julia/runtime/rtutils.jl): the value's class id against the ranges of the
# classes under K, the type its call names, as the is checker's range check reads them
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:typetagis}, target::Core.MethodInstance, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local K = (Base.unwrap_unionall(target.specTypes)::DataType).parameters[3].parameters[1]
    local type_ = t.top_type_non_nullable[]
    translate_expression(self.code_gen, args[1], type_)
    load_class_id(self.code_gen.b[], t, type_)
    emit_class_id_range_check(self.code_gen.b[], get_concrete_class_id_range(t.class_id_numbering[], K))
    return WasmBuilder.IR.NumType_i32
end

# dart's unsafeCast (intrinsics.dart:1517): the operand translated at its own type (typeOfExp), and the
# context converts it, as dart lets it (its conversion to the call's expected type a cast with no test);
# the type argument, Julia's `::Type{T}` parameter, takes no code
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:unsafe_cast}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local operand = args[2]
    return translate_expression(self.code_gen, operand, type_of_exp(self, operand))
end

# jl_is_tuple_type (julia.h:1837, src/julia/runtime/rtutils.jl): the class the DataType denotes, its
# classId field, against the ids of the closed world's tuple classes (each class a Tuple type, concrete
# or not; a tuple record, TupleRecord, is none)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:is_tuple_type}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local at = "$(julia_text(self.code_gen.enclosing_member)): jl_is_tuple_type"
    local info = get(t.class_info, DataType, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: jl_is_tuple_type where DataType has no class info"), at)
    local field = only(f for f in class_instance_fields(DataType, at) if f.name == "classId")
    translate_expression(self.code_gen, only(args), info.non_nullable_type)
    WasmBuilder.struct_get(self.code_gen.b[], info.struct_, t.field_index[field])
    local ranges = Range[Range(Val(:_), class_id(c), class_id(c)) for c in t.classes[] if c.cls isa DataType && c.cls <: Tuple]
    normalize(ranges)
    emit_class_id_range_check(self.code_gen.b[], ranges)
    return WasmBuilder.IR.NumType_i32
end

# jl_is_type_type (julia.h:1855, src/julia/runtime/rtutils.jl): the class the DataType denotes, its
# classId field, against the ids of the closed world's Type{X} classes (Base.isType, X no type variable)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:is_type_type}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local at = "$(julia_text(self.code_gen.enclosing_member)): jl_is_type_type"
    local info = get(t.class_info, DataType, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: jl_is_type_type where DataType has no class info"), at)
    local field = only(f for f in class_instance_fields(DataType, at) if f.name == "classId")
    translate_expression(self.code_gen, only(args), info.non_nullable_type)
    WasmBuilder.struct_get(self.code_gen.b[], info.struct_, t.field_index[field])
    local ranges = Range[Range(Val(:_), class_id(c), class_id(c)) for c in t.classes[] if c.cls isa DataType && Base.isType(c.cls) && !(c.cls.parameters[1] isa TypeVar)]
    normalize(ranges)
    emit_class_id_range_check(self.code_gen.b[], ranges)
    return WasmBuilder.IR.NumType_i32
end

# Record._checkRecordType (record_patch.dart:15), dart's virtual call on a record: a class-id switch over
# the record classes (src/julia/classes.jl TupleRecord, the open tuple type's classes), each class's arm
# the body dart generates for its shape (record_class_generator.dart:547 _generateCheckRecordType):
# `types` of another length answers false; each field, read from the record's struct, tested by
# _isSubtype against `types`'s element at its index, the first failing answering false; else true. A
# Julia tuple is positional, so no names are compared. Class ids count from 0 in the translator's list
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:check_record_type}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32 = WasmBuilder.IR.NumType_i32
    local at = "$(julia_text(code_gen.enclosing_member)): Record._checkRecordType"
    local top_nn = t.top_type_non_nullable[]
    local sv_info = get(t.class_info, Core.SimpleVector, nothing)
    sv_info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: Record._checkRecordType where Core.SimpleVector has no class info"), at)
    local data = only(class_instance_fields(Core.SimpleVector, at))
    local data_type = (translate_type_of_field(t, data)::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
    # each field tested by its type, Julia's tuple subtyping (src/julia/runtime/rtutils.jl
    # jl_subtype_typeof), where dart calls _isSubtype
    local field_test_mi = nir_runtime_member(t.component, jl_subtype_typeof, at)
    local type_param = signature_for_direct_call(t, field_test_mi).inputs[2]
    local record = add_local(code_gen, top_nn)
    local elements = add_local(code_gen, WasmBuilder.IR.RefType_def(data_type; nullable = false))
    translate_expression(code_gen, args[1], top_nn)
    WasmBuilder.local_set(b, record)
    translate_expression(code_gen, args[2], sv_info.non_nullable_type)
    WasmBuilder.struct_get(b, sv_info.struct_, t.field_index[data])
    WasmBuilder.local_set(b, elements)
    local ranges = [(range = Range(Val(:_), id, id), value = c) for (id, c) in zip(concrete_class_ids(t, Tuple), concrete_classes(t, Tuple))]
    WasmBuilder.local_get(b, record)
    load_class_id(b, t, top_nn)
    class_id_search(b, ranges, WasmBuilder.IR.ValueType[i32], cls -> begin
            local n = tuple_record_arity(cls)
            n === nothing && reject!(Internal("$at: class $cls under the open tuple type is no record"), at)
            local info = t.class_info[cls]
            local fields = class_instance_fields(cls, at)
            local arm = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[i32])
            # if (types.length != shape.numFields) return false;
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.local_get(b, elements)
            WasmBuilder.array_len(b)
            WasmBuilder.i32_const(b, n)
            WasmBuilder.i32_ne(b)
            WasmBuilder.br_if(b, arm)
            WasmBuilder.drop(b)
            local rec = n == 0 ? nothing : add_local(code_gen, info.non_nullable_type)
            if rec !== nothing
                WasmBuilder.local_get(b, record)
                WasmBuilder.ref_cast(b, info.non_nullable_type)
                WasmBuilder.local_set(b, rec)
            end
            # if (!_isSubtype($i, types[i])) return false; Julia's field by its type
            for k in 1:n
                WasmBuilder.i32_const(b, 0)
                WasmBuilder.local_get(b, rec)
                WasmBuilder.struct_get(b, info.struct_, t.field_index[fields[k]])
                WasmBuilder.local_get(b, elements)
                WasmBuilder.i32_const(b, k - 1)
                WasmBuilder.array_get(b, data_type)
                WasmBuilder.ref_cast(b, type_param::WasmBuilder.IR.RefType)
                call_reference(t, field_test_mi, b)
                WasmBuilder.i32_eqz(b)
                WasmBuilder.br_if(b, arm)
                WasmBuilder.drop(b)
            end
            # return true
            WasmBuilder.i32_const(b, 1)
            WasmBuilder.var"end"(b)   # arm
            nothing
        end, () -> WasmBuilder.unreachable(b))
    return i32
end

# _InterfaceType.classId (type.dart:276), a DataType value's field (src/julia/classes.jl, the kinds'
# fields): its struct.get, as dart's code generator reads an instance field
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:interface_type_class_id}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local at = "$(julia_text(self.code_gen.enclosing_member)): _InterfaceType.classId"
    local info = get(t.class_info, DataType, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: _InterfaceType.classId where DataType has no class info"), at)
    local field = only(f for f in class_instance_fields(DataType, at) if f.name == "classId")
    translate_expression(self.code_gen, only(args), info.non_nullable_type)
    WasmBuilder.struct_get(self.code_gen.b[], info.struct_, t.field_index[field])
    return WasmBuilder.IR.NumType_i32
end

# _isRecordClassId (intrinsics.dart:1485): the class id checked against the record classes' ranges,
# dart's getConcreteClassIdRange of its Record class; Julia's records are the open tuple type's
# (src/julia/classes.jl open_tuple_holds), not one range as dart asserts but each its own
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:is_record_class_id}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local ranges = get_concrete_class_id_range(t.class_id_numbering[], Tuple)
    translate_expression(self.code_gen, only(args), WasmBuilder.IR.NumType_i32)
    emit_class_id_range_check(self.code_gen.b[], ranges)
    return WasmBuilder.IR.NumType_i32
end

# ClassID.getID (intrinsics.dart:1577): the operand translated as the non-null top type, its class id
# loaded
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:get_id}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local t = translator(self)
    local type_ = t.top_type_non_nullable[]
    translate_expression(self.code_gen, only(args), type_)
    load_class_id(self.code_gen.b[], t, type_)
    return WasmBuilder.IR.NumType_i32
end

# Julia's type of a type tag (julia.h:971 jl_to_typeof, src/julia/runtime/rtutils.jl): the class id's
# entry of the table of each class's type value, the class translator.classes holds at its id (the one
# map from a class id to its class), read as a non-null DataType. The top's entry, which no value
# carries, is null, and so is the entry of each class whose type value has no constant yet
# (src/julia/classes.jl type_value_unmade, the one list of them): an as check naming one refuses at its
# statement (types.jl emitAsCheck), so no as check's failure reads a null entry.
# With `tag_of_value`, the operand is a value and its tag its class id: Julia's typeof, jl_typeof
# (julia/src/julia.h:117), a read of the value's tag, never a new type, so every answer is one of the
# table's canonical constants. A class the operand admits whose type value has no constant refuses at
# the statement, located, so no typeof reads a null entry. Julia's `nothing` is the null reference, so
# where the operand admits it the lookup takes dart's shape for an Object member on a nullable receiver
# (code_generator.dart:2258 visitInstanceGet): null branches past it to Nothing's type, as runtimeType's
# null arm answers Null's type literal
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:to_typeof}, args::Vector{NirValue}; tag_of_value::Bool = false)::WasmBuilder.IR.ValueType
    local t = translator(self)
    local b = self.code_gen.b[]
    local result = translate_type(t, DataType)
    local array_type = array_type_for_dart_type(t, Union{Nothing,DataType}; mutable_ = true)
    # the table, then the class id pushed by `index`, read as a non-null DataType
    local lookup(index::Function) = begin
