        WasmBuilder.br(b, done)
        WasmBuilder.var"end"(b)
        translate_expression(self.code_gen, NirConst(Core.Const(Nothing)), result)
        WasmBuilder.var"end"(b)
    else
        lookup(() -> (translate_expression(self.code_gen, only(args), top); load_class_id(b, t, top)))
    end
