        WasmBuilder.i64_const(b, Int64(typemax(UInt32)))
        WasmBuilder.i64_gt_u(b)
        WasmBuilder.if_(b)
        call(code_gen, nir_runtime_member(t.component, throw_out_of_memory, at))
        WasmBuilder.unreachable(b)
        WasmBuilder.var"end"(b)
