        WasmBuilder.i64_eqz(b)
        WasmBuilder.if_(b)
        raise_bounds(() -> (get_mem(); convert_type(t, b, WasmBuilder.with_nullability(repr(minfo), false), t.top_type[])), () -> WasmBuilder.i64_const(b, 1))
