            get_length()
            WasmBuilder.i64_eqz(b)
            WasmBuilder.if_(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[I32])
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.else_(b)
            defined()
            WasmBuilder.var"end"(b)
        else
            defined()
        end
        return I32
    end
    return nothing
