# A type made at run time: Julia's apply_type with an operand only run time knows (Julia folds it where
# its operands are known, so every call reaching here makes its type at run time; typeof, a read of a
# value's tag, is the to_typeof arm's). WasmTarget holds each type as one constant, canonical by
# Julia's egal (constants.jl _lowerTypeToConstant), and `===` on two DataTypes is their ref.eq on that
# ground (the identical arm, `a_data_type`), so the type is found among the statement's cases, never
# made (Julia's run time makes a Union by jl_type_union and finds any other type in its typename's
# cache, jltypes.c:1112 lookup_type), the cases made whole at compile time (src/julia/classes.jl
# apply_type_cache, the one source of its keys and types). The cases run as Julia's inliner runs a
# union split's (Compiler/src/ssair/inlining.jl:526 ir_inline_unionsplit!), in order, each a constant
# case: its test is isa on each operand whose type is not already the case's, here an operand of more
# than one value compared by ref.eq with the case's constant (isa on a Type{X} of one value is === X),
# an operand of one value compared with nothing; the first case whose tests hold answers its constant.
# Julia's differs at the end: a fully covered split with every case handled tests its last case by
# nothing (inlining.jl:544, `i == ncases && fully_covered && handled_all_cases`); WasmTarget tests it
# too, the lookup dev/formal/TypeCacheLookup.tla models, and past it is wasm's trap, as Julia's codegen
# traps where its inference proved a path unreachable (julia/src/codegen.cpp:9202, a ReturnNode with no
# value, CreateTrap). An operand whose values the cases cannot key, and a case with no constant, rejects
# at the statement, located (apply_type_cache)
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:run_time_type}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's $(nameof(f)) on $(join((dart_type_of(self, a) for a in args), ", "))"
    # an operand's value where compile time knows it, a literal or a constant binding (Julia's Const of
    # each, abstract_eval_globalref), else the type Julia inferred for it
    local operands = Any[a isa NirConst ? Some(a.c.val) :
                         a isa NirGlobal && nir_binding_is_constant(a.binding) ? Some(nir_binding_value(a.binding, at).c.val) :
                         dart_type_of(self, a) for a in args]
    local cache = apply_type_cache(t, operands, at)
    local result = translate_type(t, Union{Any[Core.Typeof(r) for (_, r) in cache]...})
    local eq = WasmBuilder.IR.RefType_eq(; nullable = true)
    # each operand of more than one value, held for the walk
    local held = Dict{Int,WasmBuilder.IR.Local}()
    for (j, a) in enumerate(args)
        operands[j] isa Some && continue
        length(unique(k[j] for (k, _) in cache)) > 1 || continue
        held[j] = add_local(code_gen, eq)
        translate_expression(code_gen, a, eq)
        WasmBuilder.local_set(b, held[j])
    end
    local done = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[result])
    for (k, r) in cache
        local miss = WasmBuilder.block(b)
        for j in sort!(collect(keys(held)))
            WasmBuilder.local_get(b, held[j])
            translate_expression(code_gen, NirConst(Core.Const(k[j])), eq)
            WasmBuilder.ref_eq(b)
            WasmBuilder.i32_eqz(b)
            WasmBuilder.br_if(b, miss)
        end
        translate_expression(code_gen, NirConst(Core.Const(r)), result)
        WasmBuilder.br(b, done)
        WasmBuilder.var"end"(b)
    end
    WasmBuilder.unreachable(b)
    WasmBuilder.var"end"(b)
    return result
end

# a memory's data operations (src/julia/wasm_array.jl): an element left #undef (Base's _unsetindex!,
# the null of its data array, array.set, dart's WasmArrayExt.[]=), and the call Julia's runtime copy makes on two
# memories (genericmemory.c jl_genericmemory_copyto): the elements of `src`'s data array from its
# reference's offset copied into `dest`'s from its own, one array.copy, dart's WasmArrayExt.copy
# (intrinsics.dart:1254), wasm's memmove; for elements admitting nothing (classes.jl `data#isSet`) their
# set flags copied the same way. An offset or count is wrapped to the i32 a wasm array takes.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" generate_static_intrinsic(::Val{:memory_data_op}, target::Core.MethodInstance)::Union{Symbol,Nothing} =
    target.def in methods(wasm_memory_copy!) ? :copy : target.def in methods(wasm_memory_unset!) ? :unset :
    target.def in methods(wasm_memory_fill!) ? :fill : nothing

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:memory_data}, op::Symbol, target::Core.MethodInstance, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): a memory's data"
    op in (:copy, :unset, :fill) || reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a memory data operation $op"), at)
    if op === :fill
        # a byte memory's every element the byte, one array.fill of its data array from 0 for its length
        # (dart's WasmArrayExt.fill, intrinsics.dart:1279)
        local M = Base.unwrap_unionall(target.specTypes).parameters[2]
        local minfo = get(t.class_info, M, nothing)
        minfo === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a memory fill where $M has no class info"), at)
        local mfs = Dict{String,ClassField}(f.name => f for f in class_instance_fields(M, at))
        local array_type = (translate_type_of_field(t, mfs["data"])::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
        local m = add_local(code_gen, minfo.non_nullable_type)
        translate_expression(code_gen, args[1], minfo.non_nullable_type)
        WasmBuilder.local_tee(b, m)
        WasmBuilder.struct_get(b, minfo.struct_, t.field_index[mfs["data"]])
        WasmBuilder.i32_const(b, 0)
        translate_expression(code_gen, args[2], WasmBuilder.unpacked(array_type.element_type[].type))
        WasmBuilder.local_get(b, m)
        WasmBuilder.struct_get(b, minfo.struct_, t.field_index[mfs["length"]])
        WasmBuilder.i32_wrap_i64(b)
        WasmBuilder.array_fill(b, array_type)
        WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
        return t.top_type[]
    end
    local R = Base.unwrap_unionall(target.specTypes).parameters[2]
    (R isa DataType && R <: GenericMemoryRef && R.parameters[1] === :not_atomic) ||
        reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a memory copy of $R, no non-atomic MemoryRef"), at)
    local M = GenericMemory{R.parameters...}
    local rinfo, minfo = get(t.class_info, R, nothing), get(t.class_info, M, nothing)
    (rinfo === nothing || minfo === nothing) && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: a memory copy where $R or $M has no class info"), at)
    local rfs = Dict{String,ClassField}(f.name => f for f in class_instance_fields(R, at))
    local mfs = Dict{String,ClassField}(f.name => f for f in class_instance_fields(M, at))
    if op === :unset
        # the element's #undef: the null of its data array and 0 in its set flags, where it can be
        # #undef (holds_reference: boxed, or inline holding a reference); an element of bits keeps its bits
        local r = add_local(code_gen, rinfo.non_nullable_type)
        translate_expression(code_gen, args[1], rinfo.non_nullable_type)
        WasmBuilder.local_set(b, r)
        if holds_reference(eltype(R))
            for name in ("data", "data#isSet")
                haskey(mfs, name) || continue
                local array_type = (translate_type_of_field(t, mfs[name])::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
                WasmBuilder.local_get(b, r)
                WasmBuilder.struct_get(b, rinfo.struct_, t.field_index[rfs["mem"]])
                WasmBuilder.struct_get(b, minfo.struct_, t.field_index[mfs[name]])
                WasmBuilder.local_get(b, r)
                WasmBuilder.struct_get(b, rinfo.struct_, t.field_index[rfs["ptr_or_offset"]])
                WasmBuilder.i32_wrap_i64(b)
                local element = array_type.element_type[].type
                element isa WasmBuilder.IR.RefType ? WasmBuilder.ref_null(b, element.heap_type) : WasmBuilder.i32_const(b, 0)
                WasmBuilder.array_set(b, array_type)
            end
        end
        WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
        return t.top_type[]
    end
    local dest = add_local(code_gen, rinfo.non_nullable_type)
    local src = add_local(code_gen, rinfo.non_nullable_type)
    local n = add_local(code_gen, WasmBuilder.IR.NumType_i32)
    translate_expression(code_gen, args[1], rinfo.non_nullable_type)
    WasmBuilder.local_set(b, dest)
    translate_expression(code_gen, args[2], rinfo.non_nullable_type)
    WasmBuilder.local_set(b, src)
    translate_expression(code_gen, args[3], WasmBuilder.IR.NumType_i64)
    WasmBuilder.i32_wrap_i64(b)
    WasmBuilder.local_set(b, n)
    # one array of the memory's (`data`, or its set flags `data#isSet`) at a reference's offset
    local at_offset(r::WasmBuilder.IR.Local, name::String) = begin
        WasmBuilder.local_get(b, r)
        WasmBuilder.struct_get(b, rinfo.struct_, t.field_index[rfs["mem"]])
        WasmBuilder.struct_get(b, minfo.struct_, t.field_index[mfs[name]])
        WasmBuilder.local_get(b, r)
        WasmBuilder.struct_get(b, rinfo.struct_, t.field_index[rfs["ptr_or_offset"]])
        WasmBuilder.i32_wrap_i64(b)
    end
    for name in ("data", "data#isSet")
        haskey(mfs, name) || continue
        local array_type = (translate_type_of_field(t, mfs[name])::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
        at_offset(dest, name)
        at_offset(src, name)
        WasmBuilder.local_get(b, n)
        WasmBuilder.array_copy(b, array_type, array_type)
    end
    # dart's void intrinsics leave the null of the top type (WasmArrayExt.copy), Julia's nothing
    WasmBuilder.ref_null(b, WasmBuilder.IR.HeapType_none)
    return t.top_type[]
end

# Julia's tuple builtin over values whose classes only run time knows, a varargs tuple's elements packed
# at a call or a tuple literal (code_generator.jl _visitArguments, visitRecordLiteral), where Julia's
# jl_f_tuple types the tuple by its values (builtins.c:946): its arity's record (src/julia/classes.jl
# TupleRecord, dart's record class of a shape, record_class_generator.dart:280), each element boxed to
# the top type, where convertType boxes every tuple flowing into an open slot. `values` holds the
# elements, each at its static type's wasm type; leaves the record, non-null.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(intrinsifier::Intrinsifier, ::Val{:open_tuple}, tuple_type::Type, values::Vector{WasmBuilder.IR.Local}, at::String)::WasmBuilder.IR.ValueType
    local self = intrinsifier.code_gen
    local t = self.translator
    local b = self.b[]
    local tt = Base.unwrap_unionall(tuple_type)
    (tt isa DataType && tt <: Tuple && length(tt.parameters) == length(values) && !any(p -> p isa Core.TypeofVararg, tt.parameters)) ||
        reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: a tuple of type $tuple_type, of no fixed length, built at run time"), "$(julia_text(self.enclosing_member))")
    local rinfo = get(t.class_info, tuple_record_class(length(values)), nothing)
    rinfo === nothing && reject!(Internal("$at: no record class for a tuple of $(length(values))"), "$(julia_text(self.enclosing_member))")
    local fields = class_instance_fields(rinfo.cls, at)
    local vals = Dict{String,Function}()
    for (k, value) in enumerate(values)
        local field = fields[k]
        local p = tt.parameters[k]
        vals[field.name] = () -> (WasmBuilder.local_get(b, value);
            convert_type(t, b, value.type, WasmBuilder.unpacked(rinfo.struct_.fields[t.field_index[field] + 1].type); boxed_class = p isa DataType && isconcretetype(p) ? p : nothing))
    end
    generate_static_intrinsic(intrinsifier, Val(:new_struct), rinfo, Dict{String,ClassField}(f.name => f for f in fields), vals)
    return rinfo.non_nullable_type
end

# Julia's `isdefined(x, f)` on a struct field, Julia's codegen arm (codegen.cpp:4864, emit_builtin_call's
# isdefined): a field named by a constant Symbol or Int of a concrete struct; an order that does not
# fit the field (an atomic order on a field that is not atomic, :not_atomic on one that is, any order
# on a field the struct lacks, an order no load takes) raises Julia's ConcurrencyViolationError
# (codegen.cpp:4910-4934); a field the struct does not have is false; one that cannot be undefined (field_may_be_null, cgutils.cpp:2768) true, as is
# one of a constant Julia holds defined where the struct or the field is immutable; else its set flag
# where it keeps one (class_is_set_field, dart's late lowering's isSet), and otherwise whether its
# reference is not null (CreateIsNotNull). A field named at run time (jl_field_isdefined_checked), an
# order other than :not_atomic, a module's or a type's binding return nothing, rejected unported at
# the call, located.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:isdefined}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32 = WasmBuilder.IR.NumType_i32
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's isdefined"
    local obj, fld = args[1], args[2]
    local T = dart_type_of(self, obj)
    T isa DataType && isconcretetype(T) && !(T <: Type) && T !== Module && !(T <: Array) || return nothing
    fld isa NirConst && (fld.c.val isa Symbol || fld.c.val isa Int) || return nothing
    # the order, jl_get_atomic_order's for a load (loading, not storing): none given, :not_atomic, an
    # atomic one a load may take, or invalid (:release and :acquire_release are a store's)
    length(args) == 3 && !(args[3] isa NirConst && args[3].c.val isa Symbol) && return nothing
    local o = length(args) == 3 ? args[3].c.val : nothing
    local order = o === nothing ? :unspecified : o === :not_atomic ? :notatomic :
        o in (:unordered, :monotonic, :acquire, :sequentially_consistent) ? :atomic : :invalid
    # Julia's emit_atomic_error (cgutils.cpp:2759): jl_atomic_error's ConcurrencyViolationError, raised
    # through the runtime's thrower, the expression never answering
    local atomic_error(msg::String) = begin
        translate_expression(code_gen, NirConst(Core.Const(msg)), translate_type(t, String))
        call(code_gen, nir_runtime_member(t.component, throw_atomic_error, at))
        WasmBuilder.unreachable(b)
        i32
    end
    order === :invalid && return atomic_error("invalid atomic ordering")
    local i = fld.c.val isa Symbol ? something(Base.fieldindex(T, fld.c.val, false), 0) : fld.c.val
    if !(1 <= i <= fieldcount(T))
        order === :unspecified || return atomic_error("isdefined: atomic ordering cannot be specified for nonexistent field")
        WasmBuilder.i32_const(b, 0)
        return i32
    end
    local isatomic = Base.isfieldatomic(T, i)
    !isatomic && order === :atomic && return atomic_error("isdefined: non-atomic field cannot be accessed atomically")
    isatomic && order === :notatomic && return atomic_error("isdefined: atomic field cannot be accessed non-atomically")
    # an atomic field's read: threads lie outside the strict subset, a gap, located
    isatomic && reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: isdefined of $T's atomic field $(fieldname(T, i))"), at)
    local known = obj isa NirConst && (!ismutabletype(T) || isconst(T, i)) && isdefined(obj.c.val, i)
    if !field_may_be_null(T, i) || known
        WasmBuilder.i32_const(b, 1)
        return i32
    end
    local info = get(t.class_info, T, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: isdefined on $T, which has no class info"), at)
    local fields = class_instance_fields(T, at)
    local field = fields[i]
    field.index == i || reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: the class layout of $T does not begin with Julia's fields"), at)
    translate_expression(code_gen, obj, info.non_nullable_type)
    local flag = class_is_set_field(field)
    if flag !== nothing
        local flag_index = t.field_index[flag]
        info.struct_.fields[flag_index + 1].type isa WasmBuilder.IR.PackedType ?
            WasmBuilder.struct_get_u(b, info.struct_, flag_index) : WasmBuilder.struct_get(b, info.struct_, flag_index)
        return i32
    end
    WasmBuilder.struct_get(b, info.struct_, t.field_index[field])
    WasmBuilder.ref_is_null(b)
    WasmBuilder.i32_eqz(b)
    return i32
end

# Julia's `_svec_ref(v, i)`: the `i`th element (from 1) of a SimpleVector's data array, dart's
# ImmutableWasmArrayExt.[] (intrinsics.dart:1223, array.get at the index wrapped to i32) behind the
# check Julia's codegen emits (emit_bounds_check over jl_svec_len, as builtins.c's jl_f__svec_ref
# checks): an index outside 1..length raises BoundsError(v, i) through the runtime's thrower
# (src/julia/runtime/rtutils.jl throw_bounds_error, jl_bounds_error_int), never a trapping array.get.
# The element is a reference of any class, the array's element type.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:svec_ref}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local i64 = WasmBuilder.IR.NumType_i64
    (dart_type_of(self, args[1]) === Core.SimpleVector && dart_type_of(self, args[2]) === Int) || return nothing
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): a SimpleVector's element"
    local sv_info = get(t.class_info, Core.SimpleVector, nothing)
    sv_info === nothing && reject!(Internal("dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic: Core.SimpleVector has no class info"), at)
    local data = only(class_instance_fields(Core.SimpleVector, at))
    local array_type = (translate_type_of_field(t, data)::WasmBuilder.IR.RefType).heap_type::WasmBuilder.IR.ArrayType
    local sv = add_local(code_gen, WasmBuilder.with_nullability(repr(sv_info), false))
    local i = add_local(code_gen, i64)
    translate_expression(code_gen, args[1], sv.type)
    WasmBuilder.local_set(b, sv)
    translate_expression(code_gen, args[2], i64)
    WasmBuilder.local_set(b, i)
    # i - 1, unsigned, at or past the length: outside 1..length (Julia's bounds check, one comparison)
    WasmBuilder.local_get(b, i)
    WasmBuilder.i64_const(b, 1)
    WasmBuilder.i64_sub(b)
    WasmBuilder.local_get(b, sv)
    WasmBuilder.struct_get(b, sv_info.struct_, t.field_index[data])
    WasmBuilder.array_len(b)
    WasmBuilder.i64_extend_i32_u(b)
    WasmBuilder.i64_ge_u(b)
    WasmBuilder.if_(b)
    WasmBuilder.local_get(b, sv)
    convert_type(t, b, sv.type, t.top_type[])
    WasmBuilder.local_get(b, i)
    call(code_gen, nir_runtime_member(t.component, throw_bounds_error, at))
    WasmBuilder.unreachable(b)
    WasmBuilder.var"end"(b)
    WasmBuilder.local_get(b, sv)
    WasmBuilder.struct_get(b, sv_info.struct_, t.field_index[data])
    WasmBuilder.local_get(b, i)
    WasmBuilder.i64_const(b, 1)
    WasmBuilder.i64_sub(b)
    WasmBuilder.i32_wrap_i64(b)
    WasmBuilder.array_get(b, array_type)
    return WasmBuilder.unpacked(array_type.element_type[].type)
end

# identical: Julia's `===`, which compares a primitive value's bits (NaN === NaN, and 0.0 !== -0.0),
# so a float is compared as the integer of its bits, where dart compares a double by value; and, where
# an operand cannot be a value compared by content (intrinsics.dart:1450 canBeValueType), the
# references (ref.eq): Julia's jl_egal_ (julia.h:1885) answers by the pointers alone when either
# operand's class is one it compares by identity (egal_by_identity: a mutable class but String,
# SimpleVector and DataType), the same object or else, by a type tag apart or a mutable class, false.
# Two DataTypes are compared by their references too: jl_egal__bitstag (builtins.c) answers a concrete
# one by its pointer and an abstract one by its name and parameters, and WasmTarget holds each type as
# one constant, canonical by Julia's egal (constants.jl _lowerTypeToConstant, the constant table keyed
# by ===), with no type made at run time (Julia's typeof reads its tag's entry of the table of type
# values, the to_typeof arm, and apply_type finds its type in the statement's cache of those constants,
# the run_time_type arm), so a reference is equal exactly where Julia's types are egal
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:identical}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local full(t::Type, w::WasmBuilder.IR.ValueType) = generate_static_intrinsic(Val(:full), t, w)
    local first = args[1]
    local second = args[2]
    local first_type = dart_type_of(self, first)
    local second_type = dart_type_of(self, second)
    local w = type_of_exp(self, first)
    # an 8- or 16-bit integer is held in its type's one form (sign- or zero-extended, Julia's ABI), so
    # two of a type are egal exactly when their i32s are equal, as jl_egal compares their bytes; a
    # promoted primitive's bits are compared at its own width (emit_bits_compare's ICmpEQ of its iN, julia/src/codegen.cpp:3455),
    # each read in the view an equality compare reads (PromoteSetCCOperands)
    local narrow = first_type isa DataType && generate_static_intrinsic(Val(:narrow), first_type) && w == generate_static_intrinsic(Val(:register), first_type)
    local extended_view() = narrow && generate_static_intrinsic(Val(:extended_view), b[], first_type)
    if first_type === second_type && (full(first_type, w) || first_type === Bool || narrow)
        translate_expression(code_gen, first, w)
        extended_view()
        w == f64 && WasmBuilder.i64_reinterpret_f64(b[])
        w == f32 && WasmBuilder.i32_reinterpret_f32(b[])
        translate_expression(code_gen, second, w)
        extended_view()
        w == f64 && WasmBuilder.i64_reinterpret_f64(b[])
        w == f32 && WasmBuilder.i32_reinterpret_f32(b[])
        (w == i64 || w == f64) ? WasmBuilder.i64_eq(b[]) : WasmBuilder.i32_eq(b[])
        return i32
    end
    first_type === String && second_type === String && return generate_static_intrinsic(self, Val(:string_egal), first, second)
    # two of one 128-bit integer class: their bits, both halves equal (the int128 arm's eq_int)
    first_type === second_type && type_expand_integer(first_type) &&
        return generate_static_intrinsic(self, Val(:int128), Core.Intrinsics.eq_int, args)
    # a value of a type below DataType (DataType itself, Type{X} of a DataType X, a Union of such) is a DataType
    local a_data_type(T::Type) = T !== Union{} && T <: DataType
    if egal_by_identity(first_type) || egal_by_identity(second_type) || (a_data_type(first_type) && a_data_type(second_type))
        translate_expression(code_gen, first, WasmBuilder.IR.RefType_eq(; nullable = true))
        translate_expression(code_gen, second, WasmBuilder.IR.RefType_eq(; nullable = true))
        WasmBuilder.ref_eq(b[])
        return i32
    end
    # two values of one immutable class whose fields are each compared by reference or by their integer
    # bits (a tuple of DataTypes, a MemoryRef's offset and memory): Julia's egal of an immutable struct
    # compares its fields (builtins.c compare_fields: the bits of an inline field, jl_egal on each
    # pointer field), so each field pair's ref.eq or integer eq, all of them
    local by_reference(F::Type) = a_data_type(F) || egal_by_identity(F)
    local by_bits(F::Type) = F isa DataType && (F <: Base.BitInteger || F === Bool)
    if first_type === second_type && first_type isa DataType && isconcretetype(first_type) && !ismutabletype(first_type) &&
            !isprimitivetype(first_type) && fieldcount(first_type) > 0
        local t = translator(self)
        local at = "$(julia_text(code_gen.enclosing_member)): === on two $(julia_text(first_type))"
        local fields = class_instance_fields(first_type, at)
        if all(f -> by_reference(f.type) || by_bits(f.type), fields)
            local info = get(t.class_info, first_type, nothing)
            info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: === on $first_type, which has no class info"), at)
            local x = add_local(code_gen, info.non_nullable_type)
            local y = add_local(code_gen, info.non_nullable_type)
            translate_expression(code_gen, first, info.non_nullable_type)
            WasmBuilder.local_set(b[], x)
            translate_expression(code_gen, second, info.non_nullable_type)
            WasmBuilder.local_set(b[], y)
            for (k, field) in enumerate(fields)
                local index = t.field_index[field]
                local storage = info.struct_.fields[index + 1].type
                local get_field(v::WasmBuilder.IR.Local) = (WasmBuilder.local_get(b[], v);
                    storage isa WasmBuilder.IR.PackedType ? WasmBuilder.struct_get_u(b[], info.struct_, index) : WasmBuilder.struct_get(b[], info.struct_, index))
                get_field(x)
                get_field(y)
                local w = WasmBuilder.unpacked(storage)
                w isa WasmBuilder.IR.RefType ? WasmBuilder.ref_eq(b[]) : w == i64 ? WasmBuilder.i64_eq(b[]) : WasmBuilder.i32_eq(b[])
                k > 1 && WasmBuilder.i32_and(b[])
            end
            return i32
        end
    end
    # two types no value has both of: never egal (julia/src/codegen.cpp:3566 emit_f_is, its disjoint
    # concrete leaf types and its exhaustive intersection test), the operands, NIR values, read for nothing
    typeintersect(first_type, second_type) === Union{} && (WasmBuilder.i32_const(b[], 0); return i32)
    # any other pair: Julia's jl_egal, each operand boxed (julia/src/codegen.cpp:3379 emit_box_compare's
    # call of jl_egal__unboxed past its pointer and type tag tests, jl_egal_'s own), the runtime's
    # (src/julia/runtime/rtutils.jl), which the closed world holds wherever such a `===` is (:egal)
    local tr = translator(self)
    translate_expression(code_gen, first, tr.top_type[])
    translate_expression(code_gen, second, tr.top_type[])
    call(code_gen, nir_runtime_member(tr.component, jl_egal, "$(julia_text(code_gen.enclosing_member)): Julia's === on $first_type, $second_type"))
    return i32
end

# Julia's `throw_methoderror(f, args...)` (julia/src/builtins.c:604), which Julia's inference writes
# where it proved no method matches a call: jl_method_error's MethodError of `f` and the tuple of the
# arguments (gf.c:3057, jl_f_tuple), raised through the runtime (src/julia/runtime/rtutils.jl
# throw_method_error), the tuple the record of its count (the open_tuple arm), as the runtime's open
# Tuple parameter holds it
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:throw_methoderror}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's throw_methoderror"
    local callee = add_local(code_gen, t.top_type[])
    translate_expression(code_gen, args[1], t.top_type[])
    WasmBuilder.local_set(b, callee)
    local types = Any[dart_type_of(self, a) for a in args[2:end]]
    local values = WasmBuilder.IR.Local[]
    for (a, T) in zip(args[2:end], types)
        local w = translate_type(t, T)
        local v = add_local(code_gen, w)
        translate_expression(code_gen, a, w)
        WasmBuilder.local_set(b, v)
        push!(values, v)
    end
    WasmBuilder.local_get(b, callee)
    generate_static_intrinsic(self, Val(:open_tuple), Tuple{types...}, values, at)
    call(code_gen, nir_runtime_member(t.component, throw_method_error, at))
    WasmBuilder.unreachable(b)
    return t.top_type[]
end

# Julia's egal of two values of any classes, jl_egal_'s body (julia.h:1885, the runtime's jl_egal,
# src/julia/runtime/rtutils.jl, calls wasm_egal): the same reference is egal; a null (Julia's
# `nothing`) is egal only to null; values of two classes are not (the type tags); else the switch over
# the closed world's concrete classes, each its class's arm of jl_egal__unboxed_ (julia.h:1874) and
# jl_egal__bitstag (builtins.c:243): a class egal compares by identity (a mutable one but String,
# SimpleVector and DataType: name->mutabl) answers no, as do the kinds, each type one canonical constant
# (constants.jl _lowerTypeToConstant, no type made at run time, A68S3), whose references were already
# compared; any other class compares its fields, builtins.c:100 compare_fields: a field of bits by its
# bits (a float's as an integer, bits_equal), a reference by jl_egal again (a null egal only to null),
# and a field holding a wasm array (a String's bytes, a SimpleVector's elements) by its length and
# elements, jl_string_tag's memcmp and compare_svec (builtins.c:87). Julia answers Bool's and Symbol's
# by their tags, its two Bools and each Symbol canonical; WasmTarget's boxed Bool is not, so it compares
# its value, and a Symbol is a mutable class compared by identity, as the inline === compares it.
# precedent(dart: the runtime's identical, intrinsics.dart:2974 MemberIntrinsic.identical: the
# references, then null and the class ids, then a boxed int's and double's values, any other class not
# identical). Julia's differs: its immutable classes compare by their fields, so each class has its arm.
# A field holding a host reference (an externref, which no eqref holds and whose bits wasm cannot read)
# is compared as dart compares two JS values, JSValue's == (js_helper.dart:42): both null egal, one null
# not, else areEqualInJS, JS's === (the runtime's jl_egal_host_references). A standalone module has no
# JS runtime (translator.dart:112 isStandalone), and no wasm instruction compares two externrefs, so
# there the comparison raises, naming the gap (the runtime's throw_host_reference_egal), never
# answering; the null cases are answered first, as JSValue's == answers them with no JS runtime. A field
# of any other wasm type rejects, located
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:egal}, args::Vector{NirValue})::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's jl_egal"
    local top = t.top_type[]
    local top_nn = t.top_type_non_nullable[]
    local egal = nir_runtime_member(t.component, jl_egal, at)
    local a = add_local(code_gen, top)
    local c = add_local(code_gen, top)
    translate_expression(code_gen, args[1], top)
    WasmBuilder.local_set(b, a)
    translate_expression(code_gen, args[2], top)
    WasmBuilder.local_set(b, c)
    local done = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[i32])
    # the same reference, or both null
    WasmBuilder.i32_const(b, 1)
    WasmBuilder.local_get(b, a)
    WasmBuilder.local_get(b, c)
    WasmBuilder.ref_eq(b)
    WasmBuilder.br_if(b, done)
    WasmBuilder.drop(b)
    # one null
    WasmBuilder.i32_const(b, 0)
    WasmBuilder.local_get(b, a)
    WasmBuilder.ref_is_null(b)
    WasmBuilder.local_get(b, c)
    WasmBuilder.ref_is_null(b)
    WasmBuilder.i32_or(b)
    WasmBuilder.br_if(b, done)
    WasmBuilder.drop(b)
    local x = add_local(code_gen, top_nn)
    local y = add_local(code_gen, top_nn)
    WasmBuilder.local_get(b, a)
    WasmBuilder.ref_as_non_null(b)
    WasmBuilder.local_set(b, x)
    WasmBuilder.local_get(b, c)
    WasmBuilder.ref_as_non_null(b)
    WasmBuilder.local_set(b, y)
    # the type tags
    WasmBuilder.i32_const(b, 0)
    WasmBuilder.local_get(b, x)
    load_class_id(b, t, top_nn)
    WasmBuilder.local_get(b, y)
    load_class_id(b, t, top_nn)
    WasmBuilder.i32_ne(b)
    WasmBuilder.br_if(b, done)
    WasmBuilder.drop(b)
    # a field pair's test, the two values on the stack at `storage`, leaving an i32
    local compare(storage::WasmBuilder.IR.StorageType, where::String) = begin
        if storage isa WasmBuilder.IR.PackedType || storage == i32
            WasmBuilder.i32_eq(b)
        elseif storage == i64
            WasmBuilder.i64_eq(b)
        elseif storage == f32
            local r = add_local(code_gen, f32)
            WasmBuilder.local_set(b, r)
            WasmBuilder.i32_reinterpret_f32(b)
            WasmBuilder.local_get(b, r)
            WasmBuilder.i32_reinterpret_f32(b)
            WasmBuilder.i32_eq(b)
        elseif storage == f64
            local r = add_local(code_gen, f64)
            WasmBuilder.local_set(b, r)
            WasmBuilder.i64_reinterpret_f64(b)
            WasmBuilder.local_get(b, r)
            WasmBuilder.i64_reinterpret_f64(b)
            WasmBuilder.i64_eq(b)
        elseif storage isa WasmBuilder.IR.RefType && WasmBuilder.is_subtype_of(storage, top)
            call(code_gen, egal)
        elseif host(storage)
            local hp = add_local(code_gen, storage)
            local hq = add_local(code_gen, storage)
            WasmBuilder.local_set(b, hq)
            WasmBuilder.local_set(b, hp)
            # two non-null references: JS's === under the JS runtime; a standalone module has no JS
            # runtime, and no wasm instruction compares two externrefs, so the comparison raises there
            local nullable = (storage::WasmBuilder.IR.RefType).nullable
            local references() = begin
                if is_standalone(t)
                    call(code_gen, nir_runtime_member(t.component, throw_host_reference_egal, at))
                    WasmBuilder.unreachable(b)
                else
                    WasmBuilder.local_get(b, hp); nullable && WasmBuilder.ref_as_non_null(b)
                    WasmBuilder.local_get(b, hq); nullable && WasmBuilder.ref_as_non_null(b)
                    call(code_gen, nir_runtime_member(t.component, jl_egal_host_references, at))
                end
            end
            if nullable
                # the null cases first, as JSValue's == answers them with no JS runtime: both null egal,
                # one null not
                local result = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[i32])
                WasmBuilder.i32_const(b, 1)
                WasmBuilder.local_get(b, hp); WasmBuilder.ref_is_null(b); WasmBuilder.local_get(b, hq); WasmBuilder.ref_is_null(b)
                WasmBuilder.i32_and(b)
                WasmBuilder.br_if(b, result)
                WasmBuilder.drop(b)
                WasmBuilder.i32_const(b, 0)
                WasmBuilder.local_get(b, hp); WasmBuilder.ref_is_null(b); WasmBuilder.local_get(b, hq); WasmBuilder.ref_is_null(b)
                WasmBuilder.i32_or(b)
                WasmBuilder.br_if(b, result)
                WasmBuilder.drop(b)
                references()
                WasmBuilder.var"end"(b)   # result
            else
                references()
            end
        elseif storage isa WasmBuilder.IR.RefType && storage.heap_type isa WasmBuilder.IR.ArrayType
            # its length and its elements, compare_svec's loop (memcmp's for bytes)
            local arr = storage.heap_type
            local element = arr.element_type[].type
            local p = add_local(code_gen, storage)
            local q = add_local(code_gen, storage)
            local n = add_local(code_gen, i32)
            local i = add_local(code_gen, i32)
            WasmBuilder.local_set(b, q)
            WasmBuilder.local_set(b, p)
            local result = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[i32])
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.local_get(b, p)
            WasmBuilder.array_len(b)
            WasmBuilder.local_tee(b, n)
            WasmBuilder.local_get(b, q)
            WasmBuilder.array_len(b)
            WasmBuilder.i32_ne(b)
            WasmBuilder.br_if(b, result)
            WasmBuilder.drop(b)
            WasmBuilder.i32_const(b, 0)
            WasmBuilder.local_set(b, i)
            local again = WasmBuilder.loop(b)
            WasmBuilder.i32_const(b, 1)
            WasmBuilder.local_get(b, i)
            WasmBuilder.local_get(b, n)
            WasmBuilder.i32_ge_u(b)
            WasmBuilder.br_if(b, result)
            WasmBuilder.drop(b)
            WasmBuilder.i32_const(b, 0)
            for v in (p, q)
                WasmBuilder.local_get(b, v)
                WasmBuilder.local_get(b, i)
                element isa WasmBuilder.IR.PackedType ? WasmBuilder.array_get_u(b, arr) : WasmBuilder.array_get(b, arr)
            end
            compare(element, where)
            WasmBuilder.i32_eqz(b)
            WasmBuilder.br_if(b, result)
            WasmBuilder.drop(b)
            WasmBuilder.local_get(b, i)
            WasmBuilder.i32_const(b, 1)
            WasmBuilder.i32_add(b)
            WasmBuilder.local_set(b, i)
            WasmBuilder.br(b, again)
            WasmBuilder.var"end"(b)   # loop
            WasmBuilder.unreachable(b)
            WasmBuilder.var"end"(b)   # result
        else
            reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: Julia's egal of $where, held as $storage, which no Julia layout compares"), at)
        end
        nothing
    end
    # a host reference, which no eqref holds
    local host(storage::WasmBuilder.IR.StorageType) = storage isa WasmBuilder.IR.RefType && !WasmBuilder.is_subtype_of(storage, WasmBuilder.IR.RefType_eq(; nullable = true))
    # jl_egal__unboxed_: the class's arm
    local ranges = [(range = Range(Val(:_), id, id), value = c) for (id, c) in zip(concrete_class_ids(t, Any), concrete_classes(t, Any))]
    WasmBuilder.local_get(b, x)
    load_class_id(b, t, top_nn)
    class_id_search(b, ranges, WasmBuilder.IR.ValueType[i32], cls -> begin
            local info = t.class_info[cls]
            local fields = Base.iskindtype(cls) || egal_by_identity(cls) ? ClassField[] : class_instance_fields(cls, at)
            if Base.iskindtype(cls) || egal_by_identity(cls)
                WasmBuilder.i32_const(b, 0)
                return nothing
            end
            if isempty(fields)
                # a class of no field: its two values are one (jl_egal__bits, a size of 0)
                WasmBuilder.i32_const(b, 1)
                return nothing
            end
            local u = add_local(code_gen, info.non_nullable_type)
            local v = add_local(code_gen, info.non_nullable_type)
            WasmBuilder.local_get(b, x)
            WasmBuilder.ref_cast(b, info.non_nullable_type)
            WasmBuilder.local_set(b, u)
            WasmBuilder.local_get(b, y)
            WasmBuilder.ref_cast(b, info.non_nullable_type)
            WasmBuilder.local_set(b, v)
            for (k, field) in enumerate(fields)
                local index = t.field_index[field]
                local storage = info.struct_.fields[index + 1].type
                # a promoted primitive's bits compared at its own size (jl_egal__bits' memcmp of
                # jl_datatype_size bytes, julia/src/builtins.c:302 jl_egal__bits), its register's bits above them dropped by
                # the zero extension within the register (getZeroExtendInReg), as LLVM's truncating store
                # of its iN writes only those bytes (LegalizeIntegerTypes.cpp:2683 PromoteIntOp_STORE)
                local promoted = generate_static_intrinsic(Val(:promoted), field.type)
                for w in (u, v)
                    WasmBuilder.local_get(b, w)
                    storage isa WasmBuilder.IR.PackedType ? WasmBuilder.struct_get_u(b, info.struct_, index) : WasmBuilder.struct_get(b, info.struct_, index)
                    promoted && generate_static_intrinsic(Val(:extended_view), b, field.type)
                end
                compare(storage isa WasmBuilder.IR.PackedType ? storage : WasmBuilder.unpacked(storage), "$cls's field $(field.name)")
                k > 1 && WasmBuilder.i32_and(b)
            end
            nothing
        end, () -> WasmBuilder.unreachable(b))
    WasmBuilder.var"end"(b)   # done
    return i32
end

# Julia's `===` on two Strings, jl_egal's: equal when their lengths are and their bytes (memcmp over
# jl_string_data), compared code unit by code unit over the two `_data` arrays (src/julia/classes.jl);
# dart compares its strings in dart code (String.==), Julia in its runtime, so the loop is Julia's
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" function generate_static_intrinsic(self::Intrinsifier, ::Val{:string_egal}, first::NirValue, second::NirValue)::WasmBuilder.IR.ValueType
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32 = WasmBuilder.IR.NumType_i32
    local at = "$(julia_text(code_gen.enclosing_member)): === on two Strings"
    local info = get(t.class_info, String, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: === on Strings where String has no class info"), at)
    local data_index = t.field_index[only(class_instance_fields(String, at))]
    local array_type = array_type_for_dart_type(t, WasmI8; mutable_ = true)
    local data_ref = WasmBuilder.IR.RefType_def(array_type; nullable = false)
    local x = add_local(code_gen, data_ref)
    local y = add_local(code_gen, data_ref)
    local n = add_local(code_gen, i32)
    local i = add_local(code_gen, i32)
    translate_expression(code_gen, first, info.non_nullable_type)
    WasmBuilder.struct_get(b, info.struct_, data_index)
    WasmBuilder.local_set(b, x)
    translate_expression(code_gen, second, info.non_nullable_type)
    WasmBuilder.struct_get(b, info.struct_, data_index)
    WasmBuilder.local_set(b, y)
    local done = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[i32])
    # the lengths
    WasmBuilder.local_get(b, x)
    WasmBuilder.array_len(b)
    WasmBuilder.local_tee(b, n)
    WasmBuilder.local_get(b, y)
    WasmBuilder.array_len(b)
    WasmBuilder.i32_ne(b)
    WasmBuilder.if_(b)
    WasmBuilder.i32_const(b, 0)
    WasmBuilder.br(b, done)
    WasmBuilder.var"end"(b)
    # the bytes, from the first
    WasmBuilder.i32_const(b, 0)
    WasmBuilder.local_set(b, i)
    local again = WasmBuilder.loop(b)
    WasmBuilder.local_get(b, i)
    WasmBuilder.local_get(b, n)
    WasmBuilder.i32_ge_u(b)
    WasmBuilder.if_(b)
    WasmBuilder.i32_const(b, 1)
    WasmBuilder.br(b, done)
    WasmBuilder.var"end"(b)
    WasmBuilder.local_get(b, x)
    WasmBuilder.local_get(b, i)
    WasmBuilder.array_get_u(b, array_type)
    WasmBuilder.local_get(b, y)
    WasmBuilder.local_get(b, i)
    WasmBuilder.array_get_u(b, array_type)
    WasmBuilder.i32_ne(b)
    WasmBuilder.if_(b)
    WasmBuilder.i32_const(b, 0)
    WasmBuilder.br(b, done)
    WasmBuilder.var"end"(b)
    WasmBuilder.local_get(b, i)
    WasmBuilder.i32_const(b, 1)
    WasmBuilder.i32_add(b)
    WasmBuilder.local_set(b, i)
    WasmBuilder.br(b, again)
    WasmBuilder.var"end"(b)
    WasmBuilder.unreachable(b)
    WasmBuilder.var"end"(b)
    return i32
end

# Julia's `nfields(x)` (codegen.cpp:4712 emit_builtin_call's nfields arm): a constant where the value's
# type tells its field count (a concrete type, its jl_datatype_nfields), else the count of the type the
# value has at run time (emit_datatype_nfields of its typeof). A value of an open tuple type is the record
# of its arity (src/julia/classes.jl TupleRecord), so the count is the class-id switch over the records the
# static type admits (dart's types.dart classIdSearch, as the run-time tuple index takes it), each arm its
# record's arity;
# an empty list rejects, located, and a class outside it is none the program can hold (A68S3), so its
# miss is unreachable. A SimpleVector or a kind's own layout counts other than its fields: none is taken
# here, and its call rejects as before
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:nfields}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i64 = WasmBuilder.IR.NumType_i64
    local T = dart_type_of(self, args[1])
    T isa DataType && T <: Tuple || return nothing
    if isconcretetype(T)
        translate_expression(code_gen, args[1], t.void_marker[])
        WasmBuilder.i64_const(b, fieldcount(T))
        return i64
    end
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's nfields of a $T"
    # the closed world's concrete classes below T, their ids read through the one reading of a type's
    # concrete classes (getConcreteClassIdRange), each id's class the translator's (translator.classes)
    local ids = concrete_class_ids(t, T)
    local classes = concrete_classes(t, T)
    isempty(classes) && reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: nfields of $T, which no class of the closed world is"), at)
    local o = add_local(code_gen, t.top_type_non_nullable[])
    translate_expression(code_gen, args[1], t.top_type_non_nullable[])
    WasmBuilder.local_tee(b, o)
    load_class_id(b, t, o.type)
    local ranges = [(range = Range(Val(:_), id, id), value = c) for (id, c) in zip(ids, classes)]
    class_id_search(b, ranges, WasmBuilder.IR.ValueType[i64], c -> WasmBuilder.i64_const(b, something(tuple_record_arity(c), fieldcount(c))), () -> WasmBuilder.unreachable(b))
    return i64
end

# Julia's `sizeof` of a value, Julia's codegen arm (codegen.cpp:4769, emit_builtin_call's sizeof): a
# SimpleVector's (1 + length) * sizeof(void*), its length the _svec_len arm's; a memory's length times
# its element size (codegen.cpp:4805: emit_genericmemorylen, cgutils.cpp:3335, its `length` field,
# times emit_genericmemoryelsize with add_isunion, a constant where the memory's type is concrete,
# generic_memory_elsize). A memory whose element size only its run-time type knows
# (emit_genericmemoryelsize's emit_datatype_size of the value's typeof) or an atomic memory rejects,
# located. A String's arm is not taken here: Base's sizeof and ncodeunits of a String reach its data's
# length through src/patch/string.jl's overlays, its one path; a String and any other value return
# null, rejected at the call, as dart's
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:sizeof}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i64 = WasmBuilder.IR.NumType_i64
    local T = dart_type_of(self, args[1])
    local sty = Base.unwrap_unionall(T)
    if sty === Core.SimpleVector
        generate_static_intrinsic(self, Val(:svec_len), Core._svec_len, args)
        WasmBuilder.i64_const(b, 1)
        WasmBuilder.i64_add(b)
        WasmBuilder.i64_const(b, sizeof(Ptr{Cvoid}))
        WasmBuilder.i64_mul(b)
        return i64
    end
    sty isa DataType && sty <: GenericMemory || return nothing
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's sizeof of a $T"
    (T isa DataType && isconcretetype(T)) ||
        reject!(Unquarantined("julia/src/cgutils.cpp:3292 emit_genericmemoryelsize: the element size of a memory of type $T, which only its run-time type's layout holds"), at)
    T.parameters[1] === :not_atomic ||
        reject!(Unquarantined("src/intrinsics.jl generateStaticIntrinsic: Julia's sizeof of the atomic memory $T"), at)
    local info = get(t.class_info, T, nothing)
    info === nothing && reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: $T has no class info"), at)
    local len = only(fld for fld in class_instance_fields(T, at) if fld.name == "length")
    translate_expression(code_gen, args[1], info.non_nullable_type)
    WasmBuilder.struct_get(b, info.struct_, t.field_index[len])
    WasmBuilder.i64_const(b, generic_memory_elsize(T, true))
    WasmBuilder.i64_mul(b)
    return i64
end

# Julia's `fieldtype` of a concrete type and a field name only run time knows: Julia's codegen inlines
# an Int index alone (codegen.cpp:4744), so the call is the runtime's jl_f_fieldtype (builtins.c:1258),
# get_fieldtype (builtins.c:1179) of a DataType, whose jl_field_index (datatype.c:1781) compares the
# name with each of the type's field names in order (a NamedTuple's its names parameter, any other
# type's jl_field_names): the first that is the same symbol answers the type of that field
# (jl_field_type, Julia's own fieldtype of the constant), and none raises jl_has_no_field_error's
# FieldError of the type and the name (rtutils.c:169, the runtime's throw_field_error). The type is the
# constant compile time knows, so its names are too, and each comparison is a test of the symbol's
# identity (each Symbol canonical, as the inline === compares it). A boundscheck flag that is not a
# Bool (JL_TYPECHK), a type compile time does not know, or one not concrete returns null, rejected at
# the call, as dart's
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:fieldtype}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's fieldtype"
    length(args) == 3 && dart_type_of(self, args[3]) !== Bool && return nothing
    dart_type_of(self, args[2]) === Symbol || return nothing
    local TT = dart_type_of(self, args[1])
    TT isa DataType && TT <: Type && length(TT.parameters) == 1 || return nothing
    local T = TT.parameters[1]
    T isa DataType && isconcretetype(T) || return nothing
    local names = T.name === NamedTuple.body.body.name ? (T.parameters[1] isa Tuple ? T.parameters[1] : ()) : T.name.names
    local fields = Pair{Symbol,Any}[n => fieldtype(T, n) for n in names]
    local result = isempty(fields) ? t.top_type[] : translate_type(t, Union{Any[Core.Typeof(ft) for (_, ft) in fields]...})
    local symbol_type = translate_type(t, Symbol)
    local name = add_local(code_gen, symbol_type)
    translate_expression(code_gen, args[2], symbol_type)
    WasmBuilder.local_set(b, name)
    local done = WasmBuilder.block(b, WasmBuilder.IR.ValueType[], WasmBuilder.IR.ValueType[result])
    for (n, ft) in fields
        local miss = WasmBuilder.block(b)
        WasmBuilder.local_get(b, name)
        translate_expression(code_gen, NirConst(Core.Const(n)), symbol_type)
        WasmBuilder.ref_eq(b)
        WasmBuilder.i32_eqz(b)
        WasmBuilder.br_if(b, miss)
        translate_expression(code_gen, NirConst(Core.Const(ft)), result)
        WasmBuilder.br(b, done)
        WasmBuilder.var"end"(b)
    end
    translate_expression(code_gen, NirConst(Core.Const(T)), translate_type(t, DataType))
    WasmBuilder.local_get(b, name)
    call(code_gen, nir_runtime_member(t.component, throw_field_error, at))
    WasmBuilder.unreachable(b)
    WasmBuilder.var"end"(b)
    return result
end

# Julia's `_svec_len`: a SimpleVector's length, jl_svec_t's own, which its wasm array carries
# (src/julia/classes.jl, `_svec_instance_fields`): the data field's array.len, a Julia Int
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:svec_len}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    dart_type_of(self, args[1]) === Core.SimpleVector || return nothing
    local sv_info = get(translator(self).class_info, Core.SimpleVector, nothing)
    sv_info === nothing && reject!(Internal("dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic: Core.SimpleVector has no class info"), "Intrinsifier.generateStaticIntrinsic")
    local data = only(class_instance_fields(Core.SimpleVector, "Intrinsifier.generateStaticIntrinsic"))
    translate_expression(code_gen, args[1], WasmBuilder.with_nullability(repr(sv_info), false))
    WasmBuilder.struct_get(b[], sv_info.struct_, translator(self).field_index[data])
    WasmBuilder.array_len(b[])
    WasmBuilder.i64_extend_i32_u(b[])
    return i64
end

# Julia's `ifelse`: both values computed, one chosen by the Bool, wasm's typed select
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:ifelse}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local w = type_of_exp(self, args[2])
    # a reference too (a 128-bit integer's struct): wasm's typed select takes any value type
    if dart_type_of(self, args[1]) === Bool && type_of_exp(self, args[3]) == w
        translate_expression(code_gen, args[2], w)
        translate_expression(code_gen, args[3], w)
        translate_expression(code_gen, args[1], i32)
        WasmBuilder.select(b[], w)
        return w
    end
    return nothing
end

# Julia's conversions, `(T, x)`: the type converted to, then the value (dart's wasmI32FromInt,
# wasmF32FromDouble and their kin), each as Julia's codegen answers: trunc_int wraps, sext_int and
# zext_int extend by their own sign (a Bool zero-extends its 0 or 1), sitofp and uitofp round to
# nearest, fpext and fptrunc are IEEE's, bitcast reinterprets bits of one width. fptosi and fptoui
# of a value the integer cannot hold give "an arbitrary value" (unsafe_trunc, the bare intrinsic),
# never an error, and natively (aarch64's fcvtzs) the value saturates and NaN is 0, which wasm's
# saturating truncation computes: no trap, which no Julia program does there (A47S1)
# the type operand a literal or a constant binding, its static type Type{T}
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:conversion}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local full(t::Type, w::WasmBuilder.IR.ValueType) = generate_static_intrinsic(Val(:full), t, w)
    local narrow(t::Type) = generate_static_intrinsic(Val(:narrow), t)
    local put_form(t::Type) = generate_static_intrinsic(Val(:put_form), b[], t)
    local signed_view(t::Type) = generate_static_intrinsic(Val(:signed_view), b[], t)
    local unsigned_view(t::Type) = generate_static_intrinsic(Val(:unsigned_view), b[], t)
    local type_operand = dart_type_of(self, args[1])
    local to = type_operand.parameters[1]
    local x = args[2]
    local from = dart_type_of(self, x)
    local from_w = type_of_exp(self, x)
    local to_w = translate_type(translator(self), to)
    local int(w::WasmBuilder.IR.ValueType) = w == i32 || w == i64
    local flt(w::WasmBuilder.IR.ValueType) = w == f32 || w == f64
    local emit::Union{Function,Nothing} = nothing
    if f === Core.Intrinsics.trunc_int && full(from, from_w) && full(to, to_w) && from_w == i64 && to_w == i32
        emit = WasmBuilder.i32_wrap_i64
    elseif f === Core.Intrinsics.sext_int && full(from, from_w) && full(to, to_w) && from_w == i32 && to_w == i64
        emit = WasmBuilder.i64_extend_i32_s
    elseif f === Core.Intrinsics.zext_int && (full(from, from_w) || from === Bool) && full(to, to_w) && from_w == i32 && to_w == i64
        emit = WasmBuilder.i64_extend_i32_u
    elseif f === Core.Intrinsics.zext_int && from === Bool && full(to, to_w) && to_w == i32
        emit = _ -> nothing
    elseif (f === Core.Intrinsics.sitofp || f === Core.Intrinsics.uitofp) && full(from, from_w) && full(to, to_w) && int(from_w) && flt(to_w)
        local s = f === Core.Intrinsics.sitofp
        emit = to_w == f64 ? (from_w == i64 ? (s ? WasmBuilder.f64_convert_i64_s : WasmBuilder.f64_convert_i64_u) : (s ? WasmBuilder.f64_convert_i32_s : WasmBuilder.f64_convert_i32_u)) :
                             (from_w == i64 ? (s ? WasmBuilder.f32_convert_i64_s : WasmBuilder.f32_convert_i64_u) : (s ? WasmBuilder.f32_convert_i32_s : WasmBuilder.f32_convert_i32_u))
    elseif (f === Core.Intrinsics.fptosi || f === Core.Intrinsics.fptoui) && full(from, from_w) && full(to, to_w) && flt(from_w) && int(to_w)
        local s = f === Core.Intrinsics.fptosi
        emit = to_w == i64 ? (from_w == f64 ? (s ? WasmBuilder.i64_trunc_sat_f64_s : WasmBuilder.i64_trunc_sat_f64_u) : (s ? WasmBuilder.i64_trunc_sat_f32_s : WasmBuilder.i64_trunc_sat_f32_u)) :
                             (from_w == f64 ? (s ? WasmBuilder.i32_trunc_sat_f64_s : WasmBuilder.i32_trunc_sat_f64_u) : (s ? WasmBuilder.i32_trunc_sat_f32_s : WasmBuilder.i32_trunc_sat_f32_u))
    elseif f === Core.Intrinsics.fpext && full(from, from_w) && full(to, to_w) && from_w == f32 && to_w == f64
        emit = WasmBuilder.f64_promote_f32
    elseif f === Core.Intrinsics.fptrunc && full(from, from_w) && full(to, to_w) && from_w == f64 && to_w == f32
        emit = WasmBuilder.f32_demote_f64
    elseif f === Core.Intrinsics.bitcast && full(from, from_w) && full(to, to_w) && sizeof(from) == sizeof(to)
        emit = from_w == to_w ? (_ -> nothing) :
               to_w == f64 ? WasmBuilder.f64_reinterpret_i64 : to_w == i64 ? WasmBuilder.i64_reinterpret_f64 :
               to_w == f32 ? WasmBuilder.f32_reinterpret_i32 : WasmBuilder.i32_reinterpret_f32
    end
    # an integer of either kind: a Julia BitInteger or a narrow one (a promoted primitive among them)
    local integer(t::Type) = t isa DataType && (t <: Base.BitInteger || narrow(t))
    if emit === nothing && (f === Core.Intrinsics.fptosi || f === Core.Intrinsics.fptoui) && full(from, from_w) && flt(from_w) && narrow(to) && integer(to)
        # a float into a narrow integer: LLVM's PromoteIntRes_FP_TO_XINT (LegalizeIntegerTypes.cpp:918), the
        # conversion at the promoted register NVT, getTypeToTransformTo (an i8 or i16 an i32, an i40 an
        # i64: the register Val(:register) names), by the opcode getPreferredFPToIntOpcode
        # (TargetLowering.h:3668) keeps where it is legal there, wasm's saturating truncation as above.
        # LLVM's arm ends in AssertZext or AssertSext, which emits nothing and asserts the narrow form;
        # here a narrow value is held in its form (translateType), so the form is computed (put_form):
        # a value out of the narrow type's range is poison in LLVM (julia/src/intrinsics.cpp:1379
        # generic_cast's FPToUI and FPToSI, no freeze), so computing the form refines it
        local s = f === Core.Intrinsics.fptosi
        local r = generate_static_intrinsic(Val(:register), to)
        translate_expression(code_gen, x, from_w)
        (r == i64 ? (from_w == f64 ? (s ? WasmBuilder.i64_trunc_sat_f64_s : WasmBuilder.i64_trunc_sat_f64_u) : (s ? WasmBuilder.i64_trunc_sat_f32_s : WasmBuilder.i64_trunc_sat_f32_u)) :
                    (from_w == f64 ? (s ? WasmBuilder.i32_trunc_sat_f64_s : WasmBuilder.i32_trunc_sat_f64_u) : (s ? WasmBuilder.i32_trunc_sat_f32_s : WasmBuilder.i32_trunc_sat_f32_u)))(b[])
        put_form(to)
        return r
    end
    if emit === nothing && (narrow(from) || narrow(to)) && integer(from) && to isa DataType
        # a conversion with a narrow side: the source read in the view the conversion needs, the
        # instruction between the registers, and the result put in its type's form. Into a promoted
        # primitive, LLVM's PromoteIntRes_TRUNCATE (LegalizeIntegerTypes.cpp:1859: the operand, truncated to
        # the promoted register where wider) and PromoteIntRes_BITCAST (:540, the operand of the same
        # register as it is); out of one, PromoteIntOp_SIGN_EXTEND (:2643) and PromoteIntOp_ZERO_EXTEND
        # (:2841), the operand extended within its register and any-extended to the result's
        local view = (f === Core.Intrinsics.sext_int || f === Core.Intrinsics.sitofp) ? signed_view :
                     (f === Core.Intrinsics.zext_int || f === Core.Intrinsics.uitofp) ? unsigned_view : (_::Type -> nothing)
        local between = nothing
        if (f === Core.Intrinsics.trunc_int || f === Core.Intrinsics.bitcast) && integer(to) && sizeof(to) <= sizeof(from)
            between = from_w == i64 && to_w == i32 ? WasmBuilder.i32_wrap_i64 : (_ -> nothing)
        elseif (f === Core.Intrinsics.sext_int || f === Core.Intrinsics.zext_int) && integer(to) && sizeof(to) >= sizeof(from)
            between = to_w == i64 && from_w == i32 ? (f === Core.Intrinsics.sext_int ? WasmBuilder.i64_extend_i32_s : WasmBuilder.i64_extend_i32_u) : (_ -> nothing)
        elseif (f === Core.Intrinsics.sitofp || f === Core.Intrinsics.uitofp) && full(to, to_w) && (to_w == f32 || to_w == f64)
            local s_ = f === Core.Intrinsics.sitofp
            between = from_w == i64 ?
                (to_w == f64 ? (s_ ? WasmBuilder.f64_convert_i64_s : WasmBuilder.f64_convert_i64_u) : (s_ ? WasmBuilder.f32_convert_i64_s : WasmBuilder.f32_convert_i64_u)) :
                (to_w == f64 ? (s_ ? WasmBuilder.f64_convert_i32_s : WasmBuilder.f64_convert_i32_u) : (s_ ? WasmBuilder.f32_convert_i32_s : WasmBuilder.f32_convert_i32_u))
        end
        between === nothing && return nothing
        translate_expression(code_gen, x, from_w)
        narrow(from) && view(from)
        between(b[])
        narrow(to) && put_form(to)
        return to_w
    end
    emit === nothing && return nothing
    translate_expression(code_gen, x, from_w)
    emit(b[])
    return to_w
end

# Julia's intrinsics on a 128-bit integer (Int128, UInt128), whose value is its class's struct of two
# i64 halves (src/julia/classes.jl), as LLVM's WebAssembly backend legalizes an i128: TypeExpandInteger,
# the low and high i64 (src/llvm/legalize_integer_types.jl). Each intrinsic is the LLVM instruction
# Julia's codegen emits for it (julia/src/intrinsics.cpp), and the instruction is the expansion
# LegalizeIntegerTypes.cpp makes of it over the halves:
#   sext_int, zext_int to 128 bits (intrinsics.cpp:1363 CreateSExt, :1367 CreateZExt):
#     ExpandIntRes_SIGN_EXTEND, ExpandIntRes_ZERO_EXTEND; trunc_int from 128 bits (:1359 CreateTrunc):
#     ExpandIntOp_TRUNCATE; bitcast between Int128 and UInt128: one LLVM type, the same halves
#   eq_int, ne_int, slt_int, ult_int, sle_int, ule_int (:1622-:1627 CreateICmp): ExpandIntOp_SETCC, a
#     literal left operand first moved right with its condition swapped (TargetLowering.cpp:4800
#     SimplifySetCC's canonicalization, which DAGCombiner runs before the legalizer)
#   add_int, sub_int (:1503 CreateAdd, :1504 CreateSub), neg_int (:1502 CreateNeg, 0 less the value):
#     ExpandIntRes_ADDSUB, an add's literal left operand first moved right (DAGCombiner.cpp:2935
#     visitADDLike's canonicalization)
#   and_int, or_int, xor_int (:1649-:1651), not_int (:1404 CreateNot, an xor with all ones):
#     ExpandIntRes_Logical
#   ctlz_int, cttz_int, ctpop_int (llvm.ctlz, llvm.cttz, llvm.ctpop, their width answered for zero):
#     ExpandIntRes_CTLZ, ExpandIntRes_CTTZ, ExpandIntRes_CTPOP; bswap_int (:1692 llvm.bswap):
#     ExpandIntRes_BSWAP, each half by the i64 byte swap (the unary map's, TargetLowering's expandBSWAP)
#   flipsign_int (:1719): both literals, their constant; a literal y, x or 0 less x by y's sign; else
#     tmp = y's arithmetic shift by 127, (x + tmp) ^ tmp: ExpandShiftByConstant, ExpandIntRes_ADDSUB
#     and ExpandIntRes_Logical
#   mul_int (:1505 CreateMul): ExpandIntRes_MUL, compiler-rt's __multi3 in place; the product reads no
#     operand order, so visitMUL's canonicalization changes nothing
#   sdiv_int, udiv_int, srem_int, urem_int (:1506-:1509 CreateSDiv and its kin): ExpandIntRes_SDIV and
#     its kin, the libcall into compiler-rt's routine, the runtime's port (src/julia/runtime/rtutils.jl);
#     their checked forms past Julia's checks first: checked_sdiv_int's divisor valid where y != 0 and
#     (y != -1 or x != typemin) (:1594), the others' where y != 0 (:1606, :1615, :1096
#     emit_checked_srem_int), else DivideError, and checked_srem_int's divisor of -1 answering 0
#   shl_int, lshr_int, ashr_int (:1653, :1666, :1679): the shift of x by y converted to 128 bits
#     (uint_cnvt), ExpandIntRes_Shift, selected (SplitRes_Select, over the halves) by y >= 128, in y's
#     type, against 0, or x's arithmetic shift by 127 for ashr_int; a literal y decides the select,
#     which Julia's IRBuilder folds
# An operand's halves are GetExpandedInteger's: a literal's ExpandIntRes_Constant, any other value's
# two fields read into i64 locals once, one value read once. Any other operation is not yet ported
# and rejects at its statement, located
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:int128}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local t = translator(self)
    local b = code_gen.b[]
    local i32, i64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64
    local I = Core.Intrinsics
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's $f on a 128-bit integer"
    local narrow(T::Type) = generate_static_intrinsic(Val(:narrow), T)
    local put_form(T::Type) = generate_static_intrinsic(Val(:put_form), b, T)
    local unsigned_view(T::Type) = generate_static_intrinsic(Val(:unsigned_view), b, T)
    local signed_view(T::Type) = generate_static_intrinsic(Val(:signed_view), b, T)
    local info_of(T::DataType) = (local i = get(t.class_info, T, nothing);
        i === nothing ? reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: the 128-bit class $T has no class info"), at) : i)
    # the halves' field indices, low then high
    local fields(T::DataType) = (local fs = class_instance_fields(T, at); (t.field_index[fs[1]], t.field_index[fs[2]]))
    local literal(v::NirValue) = v isa NirConst && v.c.val isa Union{Int128,UInt128}
    # GetExpandedInteger: the halves of a 128-bit operand
    local read = Tuple{NirValue,Tuple{WasmBuilder.IR.Local,WasmBuilder.IR.Local}}[]
    local expanded(v::NirValue) = begin
        literal(v) && return LLVM.expand_int_res_constant(v.c.val)
        for (w, h) in read
            w == v && return h
        end
        local T = dart_type_of(self, v)::DataType
        local s = add_local(code_gen, info_of(T).non_nullable_type)
        translate_expression(code_gen, v, s.type)
        WasmBuilder.local_set(b, s)
        local lo = add_local(code_gen, i64); local hi = add_local(code_gen, i64)
        local (l, h) = fields(T)
        WasmBuilder.local_get(b, s); WasmBuilder.struct_get(b, info_of(T).struct_, l); WasmBuilder.local_set(b, lo)
        WasmBuilder.local_get(b, s); WasmBuilder.struct_get(b, info_of(T).struct_, h); WasmBuilder.local_set(b, hi)
        push!(read, (v, (lo, hi)))
        (lo, hi)
    end
    # a new value of the 128-bit class T from its halves; the class a box's layout, its class id alone
    # ahead of its value (dart's boxed classes sit below the top type)
    local make(T::DataType, h::Tuple{Union{WasmBuilder.IR.Local,Int64},Union{WasmBuilder.IR.Local,Int64}}) = begin
        local info = info_of(T)
        local halves = class_instance_fields(T, at)
        generate_static_intrinsic(self, Val(:new_struct), info, Dict{String,ClassField}(f.name => f for f in halves),
            Dict{String,Function}(halves[1].name => () -> sd_get(b, h[1]), halves[2].name => () -> sd_get(b, h[2])))
        info.non_nullable_type
    end
    if length(args) == 2 && (local c = dart_type_of(self, args[1]); c isa DataType && c <: Type && length(c.parameters) == 1)
        local to = c.parameters[1]
        to isa Type || return nothing
        local x = args[2]
        local from = dart_type_of(self, x)
        if (f === I.sext_int || f === I.zext_int) && type_expand_integer(to) && from isa DataType && (from <: Base.BitInteger || from === Bool || narrow(from)) && sizeof(from) <= 8
            # the operand in its wasm type, a narrow integer extended within it (a promoted primitive's
            # extension LLVM's PromoteIntOp_SIGN_EXTEND or PromoteIntOp_ZERO_EXTEND, ExpandIntRes_SIGN_EXTEND's
            # and ExpandIntRes_ZERO_EXTEND's operand)
            local from_w = type_of_exp(self, x)
            translate_expression(code_gen, x, from_w)
            narrow(from) && (f === I.sext_int ? signed_view(from) : unsigned_view(from))
            local op = add_local(code_gen, from_w)
            WasmBuilder.local_set(b, op)
            return make(to, f === I.sext_int ? LLVM.expand_int_res_sign_extend(b, op) : LLVM.expand_int_res_zero_extend(b, op))
        elseif f === I.trunc_int && type_expand_integer(from) && to isa DataType && to <: Base.BitInteger && sizeof(to) <= 8
            local to_w = translate_type(t, to)
            LLVM.expand_int_op_truncate(b, expanded(x), to_w)
            narrow(to) && put_form(to)
            return to_w
        elseif f === I.bitcast && type_expand_integer(from) && type_expand_integer(to)
            return make(to, expanded(x))
        end
        return nothing
    end
    local cc = f === I.eq_int ? :SETEQ : f === I.ne_int ? :SETNE : f === I.slt_int ? :SETLT : f === I.ult_int ? :SETULT :
               f === I.sle_int ? :SETLE : f === I.ule_int ? :SETULE : nothing
    if length(args) == 2 && cc !== nothing
        local T = dart_type_of(self, args[1])
        type_expand_integer(T) && dart_type_of(self, args[2]) === T || return nothing
        local (l, r) = (expanded(args[1]), expanded(args[2]))
        # DAGCombiner::visitSETCC (llvm/lib/CodeGen/SelectionDAG/DAGCombiner.cpp:14706) simplifies the
        # 128-bit setcc before the type legalizer expands it (SimplifySetCC: decided, or a literal on the
        # left moved right, or a constant bound rewritten). The setcc it rewrites to is expanded as it
        # stands: DAGCombiner's worklist would visit it again (a moved literal's x >= C read as x > C-1),
        # which this arm does not port; each rewrite answers the same compare
        local s = LLVM.simplify_set_cc(l, r, cc)
        if s isa Bool
            WasmBuilder.local_get(b, LLVM.get_bool_constant(b, s))
            return i32
        end
        s === nothing || ((l, r, cc) = s)
        WasmBuilder.local_get(b, LLVM.expand_int_op_setcc(b, l, r, cc))
        return i32
    end
    if length(args) == 2 && (f === I.shl_int || f === I.lshr_int || f === I.ashr_int) && type_expand_integer(dart_type_of(self, args[1]))
        local T = dart_type_of(self, args[1])::DataType
        local A = dart_type_of(self, args[2])
        (A isa DataType && (A <: Base.BitInteger || A === Bool)) || return nothing
        local opc = f === I.shl_int ? :SHL : f === I.lshr_int ? :SRL : :SRA
        local x = expanded(args[1])
        # the select's other value: 0, or for ashr_int x's arithmetic shift by 127, a constant amount
        local other() = f === I.ashr_int ? LLVM.expand_shift_by_constant(b, :SRA, x, Int64(127)) : (Int64(0), Int64(0))
        local y = args[2]
        if y isa NirConst
            # a literal amount, unsigned in its own type, decides the select
            local n = A === Bool ? UInt128(y.c.val::Bool) : UInt128(reinterpret(unsigned(A), y.c.val))
            n >= 128 && return make(T, other())
            return make(T, LLVM.expand_int_res_shift(b, opc, x, Int64(n)))
        end
        # the amount converted to 128 bits and truncated to the libcall's i32: its low 64 bits, held in
        # an i64; and y >= 128 compared in y's own type
        local amt = add_local(code_gen, i64)
        local big = if type_expand_integer(A)
            local yh = expanded(y)
            sd_get(b, yh[1]); WasmBuilder.local_set(b, amt)
            LLVM.expand_int_op_setcc(b, yh, (Int64(128), Int64(0)), :SETUGE)
        else
            local aw = type_of_exp(self, y)
            translate_expression(code_gen, y, aw)
            narrow(A) && unsigned_view(A)
            local ay = add_local(code_gen, aw)
            WasmBuilder.local_set(b, ay)
            WasmBuilder.local_get(b, ay); aw == i32 && WasmBuilder.i64_extend_i32_u(b); WasmBuilder.local_set(b, amt)
            local g = add_local(code_gen, i32)
            WasmBuilder.local_get(b, ay)
            aw == i32 ? (WasmBuilder.i32_const(b, 128); WasmBuilder.i32_ge_u(b)) : (WasmBuilder.i64_const(b, Int64(128)); WasmBuilder.i64_ge_u(b))
            WasmBuilder.local_set(b, g)
            g
        end
        local shifted = LLVM.expand_int_res_shift(b, opc, x, amt)
        return make(T, LLVM.split_res_select(b, big, other(), shifted))
    end
    local T = dart_type_of(self, args[1])
    type_expand_integer(T) && all(a -> dart_type_of(self, a) === T, args) || return nothing
    local T_ = T::DataType
    if length(args) == 2 && (f === I.add_int || f === I.sub_int)
        local (l, r) = (args[1], args[2])
        # visitADDLike: an add's literal on the left moves right
        f === I.add_int && literal(l) && !literal(r) && ((l, r) = (r, l))
        return make(T_, LLVM.expand_int_res_addsub(b, f === I.add_int, expanded(l), expanded(r)))
    elseif length(args) == 1 && f === I.neg_int
        return make(T_, LLVM.expand_int_res_addsub(b, false, (Int64(0), Int64(0)), expanded(args[1])))
    elseif length(args) == 2 && (f === I.and_int || f === I.or_int || f === I.xor_int)
        local opc = f === I.and_int ? :AND : f === I.or_int ? :OR : :XOR
        return make(T_, LLVM.expand_int_res_logical(b, opc, expanded(args[1]), expanded(args[2])))
    elseif length(args) == 1 && f === I.not_int
        return make(T_, LLVM.expand_int_res_logical(b, :XOR, expanded(args[1]), (Int64(-1), Int64(-1))))
    elseif length(args) == 1 && f === I.ctlz_int
        return make(T_, LLVM.expand_int_res_ctlz(b, expanded(args[1])))
    elseif length(args) == 1 && f === I.cttz_int
        return make(T_, LLVM.expand_int_res_cttz(b, expanded(args[1])))
    elseif length(args) == 1 && f === I.ctpop_int
        return make(T_, LLVM.expand_int_res_ctpop(b, expanded(args[1])))
    elseif length(args) == 1 && f === I.bswap_int
        return make(T_, LLVM.expand_int_res_bswap(b, expanded(args[1]), () -> Intrinsifier__unary_operator_map[][i64][I.bswap_int](code_gen)))
    elseif length(args) == 2 && f === I.flipsign_int
        local x = args[1]
        local y = args[2]
        if literal(y)
            # a literal y: x where y is not negative, else 0 less x; both literals, their constant
            literal(x) && return make(T_, LLVM.expand_int_res_constant(reinterpret(Int128, y.c.val) >= 0 ? x.c.val : -x.c.val))
            reinterpret(Int128, y.c.val) >= 0 && return make(T_, expanded(x))
            return make(T_, LLVM.expand_int_res_addsub(b, false, (Int64(0), Int64(0)), expanded(x)))
        end
        # tmp = y >> 127 (arithmetic, a constant amount), (x + tmp) ^ tmp
        local tmp = LLVM.expand_shift_by_constant(b, :SRA, expanded(y), Int64(127))
        return make(T_, LLVM.expand_int_res_logical(b, :XOR, LLVM.expand_int_res_addsub(b, true, expanded(x), tmp), tmp))
    elseif length(args) == 2 && f === I.mul_int
        return make(T_, LLVM.expand_int_res_mul(b, expanded(args[1]), expanded(args[2])))
    elseif length(args) == 2 && (f === I.checked_sdiv_int || f === I.checked_srem_int || f === I.checked_udiv_int || f === I.checked_urem_int ||
                                 f === I.sdiv_int || f === I.srem_int || f === I.udiv_int || f === I.urem_int)
        local signed = f === I.checked_sdiv_int || f === I.checked_srem_int || f === I.sdiv_int || f === I.srem_int
        local quotient = f === I.checked_sdiv_int || f === I.checked_udiv_int || f === I.sdiv_int || f === I.udiv_int
        local checked = f === I.checked_sdiv_int || f === I.checked_srem_int || f === I.checked_udiv_int || f === I.checked_urem_int
        local RT = signed ? Int128 : UInt128
        local x = expanded(args[1])
        local y = expanded(args[2])
        # makeLibCall: each operand a value of the routine's class over the same halves, the routine
        # RTLIB names (WebAssemblyRuntimeLibcallSignatures.cpp:124 SDIV_I128, :129 UDIV_I128, :134
        # SREM_I128, :139 UREM_I128), its result split into its halves (SplitInteger)
        local make_lib_call(lc::Symbol, ops::Tuple{Tuple{Union{WasmBuilder.IR.Local,Int64},Union{WasmBuilder.IR.Local,Int64}},Tuple{Union{WasmBuilder.IR.Local,Int64},Union{WasmBuilder.IR.Local,Int64}}}) = begin
            local routine = lc === :SDIV_I128 ? divti3 : lc === :SREM_I128 ? modti3 : lc === :UDIV_I128 ? udivti3 : lc === :UREM_I128 ? umodti3 :
                reject!(Internal("src/intrinsics.jl generateStaticIntrinsic: $lc is no 128-bit division libcall"), at)
            make(RT, ops[1]); make(RT, ops[2])
            call(code_gen, nir_runtime_member(t.component, routine, at))
            local r = add_local(code_gen, info_of(RT).non_nullable_type)
            WasmBuilder.local_set(b, r)
            local lo = add_local(code_gen, i64); local hi = add_local(code_gen, i64)
            local (l, h) = fields(RT)
            WasmBuilder.local_get(b, r); WasmBuilder.struct_get(b, info_of(RT).struct_, l); WasmBuilder.local_set(b, lo)
            WasmBuilder.local_get(b, r); WasmBuilder.struct_get(b, info_of(RT).struct_, h); WasmBuilder.local_set(b, hi)
            (lo, hi)
        end
        local divide() = signed ? (quotient ? LLVM.expand_int_res_sdiv((x, y), make_lib_call) : LLVM.expand_int_res_srem((x, y), make_lib_call)) :
                                  (quotient ? LLVM.expand_int_res_udiv((x, y), make_lib_call) : LLVM.expand_int_res_urem((x, y), make_lib_call))
        # raise_exception_unless (julia/src/cgutils.cpp:1586): Julia's DivideError where the condition fails
        local raise_unless(cond::WasmBuilder.IR.Local) = begin
            WasmBuilder.local_get(b, cond); WasmBuilder.i32_eqz(b)
            WasmBuilder.if_(b)
            call(code_gen, nir_runtime_member(t.component, throw_divide_error, at))
            WasmBuilder.unreachable(b)
            WasmBuilder.var"end"(b)
        end
        if f === I.checked_sdiv_int
            # intrinsics.cpp:1594: the divisor valid where y != 0 and (y != -1 or x != typemin)
            local nz = LLVM.expand_int_op_setcc(b, y, (Int64(0), Int64(0)), :SETNE)
            local nm1 = LLVM.expand_int_op_setcc(b, y, (Int64(-1), Int64(-1)), :SETNE)
            local nmin = LLVM.expand_int_op_setcc(b, x, LLVM.expand_int_res_constant(typemin(Int128)), :SETNE)
            local valid = add_local(code_gen, i32)
            WasmBuilder.local_get(b, nz); WasmBuilder.local_get(b, nm1); WasmBuilder.local_get(b, nmin)
            WasmBuilder.i32_or(b); WasmBuilder.i32_and(b); WasmBuilder.local_set(b, valid)
            raise_unless(valid)
        elseif checked
            # :1606 checked_udiv_int, :1615 checked_urem_int and :1096 emit_checked_srem_int: y != 0
            raise_unless(LLVM.expand_int_op_setcc(b, y, (Int64(0), Int64(0)), :SETNE))
        end
        if f === I.checked_srem_int
            # emit_checked_srem_int: a divisor of -1 answers 0 (rem(typemin, -1) is undefined in LLVM),
            # any other the SRem, the two joined by a phi
            local m1 = LLVM.expand_int_op_setcc(b, y, (Int64(-1), Int64(-1)), :SETEQ)
            local rl = add_local(code_gen, i64); local rh = add_local(code_gen, i64)
            WasmBuilder.local_get(b, m1)
            WasmBuilder.if_(b)
            WasmBuilder.i64_const(b, 0); WasmBuilder.local_set(b, rl); WasmBuilder.i64_const(b, 0); WasmBuilder.local_set(b, rh)
            WasmBuilder.else_(b)
            local sr = divide()
            sd_get(b, sr[1]); WasmBuilder.local_set(b, rl); sd_get(b, sr[2]); WasmBuilder.local_set(b, rh)
            WasmBuilder.var"end"(b)
            return make(T_, (rl, rh))
        end
        return make(T_, divide())
    end
    return nothing
end

# Julia's have_fma(T): Julia's codegen emits julia.cpu.have_fma.f32 or .f64 for a constant Float32 or
# Float64 (julia/src/intrinsics.cpp:1408), which its CPU-features pass lowers by the target
# (julia/src/llvm-cpufeatures.cpp:40 always_have_fma: true on AArch64; :50 have_fma by the target's
# features elsewhere). WasmTarget answers as the native host its differential oracle runs on, an FMA
# host: true. Its fma is Julia's software fma, correctly rounded (src/patch/floatfuncs.jl: Base's fma
# and muladd are fma_emulated), so the algorithms Base picks on an FMA host (Math.two_mul, hypot's
# correctly rounded branch) compute native's bits; LLVM's WebAssembly backend would answer false and
# round muladd twice, which differs from native in the last bit (the corpus's bit_exact_math). Any
# other operand is Julia's runtime call, which rejects
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:have_fma}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local T = dart_type_of(self, args[1])
    T === Type{Float64} || T === Type{Float32} || return nothing
    WasmBuilder.i32_const(self.code_gen.b[], 1)
    return WasmBuilder.IR.NumType_i32
end

# Julia's donotdelete(args...): its codegen (julia/src/codegen.cpp:4988 emit_builtin_call) makes the
# call's value the constant `nothing` and passes each argument that has a run-time value (obj.V: not a
# constant, julia/src/codegen.cpp:2245 mark_julia_const, nor a ghost, nir_carries_data) to julia.donotdelete, a vararg
# call that reads nothing of them (julia/src/builtins.c:2060 jl_f_donotdelete returns jl_nothing).
# WasmTarget differs: wasm has no call that only keeps its operands live, so each such argument is
# translated at its own type and dropped, the value consumed as the vararg call consumes it, and the
# result is the `nothing` constant, as dart's exportWasmFunction (intrinsics.dart:1555) gives its null
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:donotdelete}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    for a in args
        (a isa NirConst || !nir_carries_data(dart_type_of(self, a))) && continue
        translate_expression(code_gen, a, type_of_exp(self, a))
        WasmBuilder.drop(code_gen.b[])
    end
    local nothing_type = translate_type(translator(self), Nothing)
    translate_expression(code_gen, NirConst(Core.Const(nothing)), nothing_type)
    return nothing_type
end

# Julia's fpiseq(x, y): both NaN, or the same bits (julia/src/intrinsics.cpp:1639: fcmp uno of each,
# their and, or'd with the integers' icmp eq), so NaN is egal to every NaN and 0.0 is not -0.0
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:fpiseq}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b[]
    local i32, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local t = dart_type_of(self, args[1])
    (t === Float64 || t === Float32) && dart_type_of(self, args[2]) === t || return nothing
    local w = t === Float64 ? f64 : f32
    local x = add_local(code_gen, w)
    local y = add_local(code_gen, w)
    translate_expression(code_gen, args[1], w)
    WasmBuilder.local_set(b, x)
    translate_expression(code_gen, args[2], w)
    WasmBuilder.local_set(b, y)
    local uno(v::WasmBuilder.IR.Local) = (WasmBuilder.local_get(b, v); WasmBuilder.local_get(b, v); w == f64 ? WasmBuilder.f64_ne(b) : WasmBuilder.f32_ne(b))
    local bits(v::WasmBuilder.IR.Local) = (WasmBuilder.local_get(b, v); w == f64 ? WasmBuilder.i64_reinterpret_f64(b) : WasmBuilder.i32_reinterpret_f32(b))
    uno(x)
    uno(y)
    WasmBuilder.i32_and(b)
    bits(x)
    bits(y)
    w == f64 ? WasmBuilder.i64_eq(b) : WasmBuilder.i32_eq(b)
    WasmBuilder.i32_or(b)
    return i32
end

# Julia's flipsign_int(x, y): x where y is not negative, else its wrapping negation (Julia's
# codegen: a select over y >= 0); x and y of one integer type, full-width or narrow
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:flipsign}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local full(t::Type, w::WasmBuilder.IR.ValueType) = generate_static_intrinsic(Val(:full), t, w)
    local x = args[1]
    local w = type_of_exp(self, x)
    local t = dart_type_of(self, x)
    # a narrow integer's sign is read sign-extended within its register (the signed compare's
    # PromoteSetCCOperands), and the result put in its type's form
    local narrow = generate_static_intrinsic(Val(:narrow), t) && w == generate_static_intrinsic(Val(:register), t)
    (w == i32 || w == i64) && (full(t, w) || narrow) && dart_type_of(self, args[2]) === t || return nothing
    local tmp = add_local(code_gen, w)
    local zero() = w == i64 ? WasmBuilder.i64_const(b[], 0) : WasmBuilder.i32_const(b[], 0)
    translate_expression(code_gen, x, w)
    WasmBuilder.local_tee(b[], tmp)
    zero()
    WasmBuilder.local_get(b[], tmp)
    w == i64 ? WasmBuilder.i64_sub(b[]) : WasmBuilder.i32_sub(b[])
    translate_expression(code_gen, args[2], w)
    narrow && generate_static_intrinsic(Val(:signed_view), b[], t)
    zero()
    w == i64 ? WasmBuilder.i64_ge_s(b[]) : WasmBuilder.i32_ge_s(b[])
    WasmBuilder.select(b[], w)
    narrow && generate_static_intrinsic(Val(:put_form), b[], t)
    return w
end

# Julia's shifts, as its codegen answers them: the count is unsigned, and a count of the width or
# more shifts every bit out (0 for shl_int and lshr_int, the sign for ashr_int), where wasm's
# shift counts modulo the width; the count is converted to the value's type for the instruction
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:shift}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local full(t::Type, w::WasmBuilder.IR.ValueType) = generate_static_intrinsic(Val(:full), t, w)
    local narrow(t::Type) = generate_static_intrinsic(Val(:narrow), t)
    local put_form(t::Type) = generate_static_intrinsic(Val(:put_form), b[], t)
    local signed_view(t::Type) = generate_static_intrinsic(Val(:signed_view), b[], t)
    local unsigned_view(t::Type) = generate_static_intrinsic(Val(:unsigned_view), b[], t)
    local x = args[1]
    local y = args[2]
    local xw = type_of_exp(self, x)
    local yw = type_of_exp(self, y)
    local xt = dart_type_of(self, x)
    local yt = dart_type_of(self, y)
    local int_operand(t::Type, w::WasmBuilder.IR.ValueType) = (full(t, w) || narrow(t)) && (w == i32 || w == i64)
    (int_operand(xt, xw) && int_operand(yt, yw)) || return nothing
    # the width is the value's own, a narrow integer's (an 8- or 16-bit one, a promoted primitive) its type's
    local width = 8 * sizeof(xt)
    local count = add_local(code_gen, yw)
    local xconst(v::Int) = xw == i64 ? WasmBuilder.i64_const(b[], v) : WasmBuilder.i32_const(b[], v)
    local push_count() = begin
        translate_expression(code_gen, y, yw)
        # a promoted count is compared unsigned at its own width (the ICmpUGE of Julia's shift), read in
        # the view an unsigned compare reads (PromoteSetCCOperands)
        narrow(yt) && generate_static_intrinsic(Val(:extended_view), b[], yt)
        WasmBuilder.local_tee(b[], count)
        yw == xw || (xw == i32 ? WasmBuilder.i32_wrap_i64(b[]) : WasmBuilder.i64_extend_i32_u(b[]))
    end
    local push_out_of_range() = begin
        WasmBuilder.local_get(b[], count)
        yw == i64 ? WasmBuilder.i64_const(b[], width) : WasmBuilder.i32_const(b[], width)
        yw == i64 ? WasmBuilder.i64_ge_u(b[]) : WasmBuilder.i32_ge_u(b[])
    end
    if f === Core.Intrinsics.ashr_int
        translate_expression(code_gen, x, xw)
        narrow(xt) && signed_view(xt)
        xconst(width - 1)
        push_count()
        push_out_of_range()
        WasmBuilder.select(b[], xw)
        xw == i64 ? WasmBuilder.i64_shr_s(b[]) : WasmBuilder.i32_shr_s(b[])
    else
        xconst(0)
        translate_expression(code_gen, x, xw)
        narrow(xt) && f === Core.Intrinsics.lshr_int && unsigned_view(xt)
        push_count()
        if f === Core.Intrinsics.shl_int
            xw == i64 ? WasmBuilder.i64_shl(b[]) : WasmBuilder.i32_shl(b[])
        else
            xw == i64 ? WasmBuilder.i64_shr_u(b[]) : WasmBuilder.i32_shr_u(b[])
        end
        push_out_of_range()
        WasmBuilder.select(b[], xw)
    end
    narrow(xt) && put_form(xt)
    return xw
end

# an 8- or 16-bit integer's arithmetic, comparison and bitwise operations, its operands of one
# type: each in the view its operation reads, the i32 instruction, the result in its type's form
# a checked division or remainder, as Julia's codegen emits it (src/intrinsics.cpp): DivideError raised,
# by the runtime's thrower (src/julia/runtime/rtutils.jl throw_divide_error, jl_diverror_exception),
# at a zero divisor, and for checked_sdiv_int at typemin ÷ -1 too, its type's own typemin; else the
# raw operation, which then never traps (wasm's rem_s answers 0 at typemin rem -1, as
# emit_checked_srem_int's own -1 case does). An 8- or 16-bit operand is read in its operation's view
# and the result put back in its type's form. dart raises its division error in dart code
# (boxed_int.dart's `~/`), Julia in its codegen, so the arm is Julia's.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:checked_division}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = code_gen.b[]
    local I = Core.Intrinsics
    local t = dart_type_of(self, args[1])
    (t isa DataType && t <: Base.BitInteger && sizeof(t) <= 8 && dart_type_of(self, args[2]) === t) || return nothing
    local w = sizeof(t) == 8 ? WasmBuilder.IR.NumType_i64 : WasmBuilder.IR.NumType_i32
    local narrow = sizeof(t) < 4
    local signed = f === I.checked_sdiv_int || f === I.checked_srem_int
    local raw = f === I.checked_sdiv_int ? I.sdiv_int : f === I.checked_srem_int ? I.srem_int :
                f === I.checked_udiv_int ? I.udiv_int : I.urem_int
    local operand(a::NirValue) = begin
        local l = add_local(code_gen, w)
        translate_expression(code_gen, a, w)
        narrow && (signed ? generate_static_intrinsic(Val(:signed_view), b, t) : generate_static_intrinsic(Val(:unsigned_view), b, t))
        WasmBuilder.local_set(b, l)
        l
    end
    local x = operand(args[1])
    local y = operand(args[2])
    local konst(v::Integer) = w == WasmBuilder.IR.NumType_i64 ? WasmBuilder.i64_const(b, Int64(v)) : WasmBuilder.i32_const(b, Int64(Int32(v)))
    local eqz() = w == WasmBuilder.IR.NumType_i64 ? WasmBuilder.i64_eqz(b) : WasmBuilder.i32_eqz(b)
    local eq() = w == WasmBuilder.IR.NumType_i64 ? WasmBuilder.i64_eq(b) : WasmBuilder.i32_eq(b)
    # the condition Julia raises on: y == 0, or, signed division, y == -1 and x == typemin
    WasmBuilder.local_get(b, y)
    eqz()
    if f === I.checked_sdiv_int
        WasmBuilder.local_get(b, y)
        konst(-1)
        eq()
        WasmBuilder.local_get(b, x)
        konst(typemin(t))
        eq()
        WasmBuilder.i32_and(b)
        WasmBuilder.i32_or(b)
    end
    WasmBuilder.if_(b)
    call(code_gen, nir_runtime_member(translator(self).component, throw_divide_error, "$(julia_text(code_gen.enclosing_member)): a checked division"))
    WasmBuilder.unreachable(b)
    WasmBuilder.var"end"(b)
    WasmBuilder.local_get(b, x)
    WasmBuilder.local_get(b, y)
    Intrinsifier__binary_operator_map[][w][w][raw](code_gen)
    narrow && generate_static_intrinsic(Val(:put_form), b, t)
    return w
end

# a checked multiplication, Julia's checked_smul_int and checked_umul_int, as its codegen emits it
# (julia/src/intrinsics.cpp:1563): LLVM's llvm.smul.with.overflow or llvm.umul.with.overflow of the two
# operands, whose two results are the Tuple{T, Bool} emit_intrinsic names (jl_apply_tuple_type_v of the
# operand's type and Bool), built as that tuple's own class is (visitRecordLiteral's layout): the
# product's low bits and the overflow flag, each as LLVM's legalizer expands the MULO on wasm
# (src/llvm/target_lowering.jl expand_mulo), a literal right operand its constant. An 8- or 16-bit
# operand's MULO is first promoted to the i32 (PromoteIntRes_XMULO), not ported: rejected, located.
# dart's int multiplication wraps, with no overflow test, so the arm is Julia's.
@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:checked_multiplication}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = code_gen.b[]
    local at = "$(julia_text(code_gen.enclosing_member)): Julia's $f"
    local t = dart_type_of(self, args[1])
    (t isa DataType && t <: Base.BitInteger && sizeof(t) <= 8 && dart_type_of(self, args[2]) === t) || return nothing
    sizeof(t) < 4 && reject!(Unported("llvm/lib/CodeGen/SelectionDAG/LegalizeIntegerTypes.cpp:2018 DAGTypeLegalizer::PromoteIntRes_XMULO"), "$at on $t")
    local w = sizeof(t) == 8 ? WasmBuilder.IR.NumType_i64 : WasmBuilder.IR.NumType_i32
    local x = add_local(code_gen, w)
    translate_expression(code_gen, args[1], w)
    WasmBuilder.local_set(b, x)
    local y = if args[2] isa NirConst
        # a literal: the constant SDValue, its bits in an Int64 (an i32's sign-extended, as i32.const reads it)
        local v = args[2].c.val::t
        sizeof(t) == 8 ? v % Int64 : Int64(v % Int32)
    else
        local l = add_local(code_gen, w)
        translate_expression(code_gen, args[2], w)
        WasmBuilder.local_set(b, l)
        l
    end
    local lo, overflow = LLVM.expand_mulo(b, f === Core.Intrinsics.checked_smul_int, w, x, y)
    local T = Tuple{t,Bool}
    local info, fs = generate_static_intrinsic(self, Val(:fields_of), T, at)
    generate_static_intrinsic(self, Val(:new_struct), info, fs, Dict{String,Function}(
        "1" => () -> WasmBuilder.local_get(b, lo), "2" => () -> WasmBuilder.local_get(b, overflow)))
    return info.non_nullable_type
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:narrow_operator}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    local b = self.code_gen.b
    local i32, i64, f32, f64 = WasmBuilder.IR.NumType_i32, WasmBuilder.IR.NumType_i64, WasmBuilder.IR.NumType_f32, WasmBuilder.IR.NumType_f64
    local put_form(t::Type) = generate_static_intrinsic(Val(:put_form), b[], t)
    local signed_view(t::Type) = generate_static_intrinsic(Val(:signed_view), b[], t)
    local unsigned_view(t::Type) = generate_static_intrinsic(Val(:unsigned_view), b[], t)
    local extended_view(t::Type) = generate_static_intrinsic(Val(:extended_view), b[], t)
    local t = dart_type_of(self, args[1])
    # the register the integer is held in: an i32, or a promoted primitive's i64
    local w = generate_static_intrinsic(Val(:register), t)
    local I = Core.Intrinsics
    local signed_ops = (I.sdiv_int, I.srem_int, I.slt_int, I.sle_int)
    local unsigned_ops = (I.udiv_int, I.urem_int, I.ult_int, I.ule_int)
    local equality_ops = (I.eq_int, I.ne_int)
    local plain_ops = (I.add_int, I.sub_int, I.mul_int, I.and_int, I.or_int, I.xor_int)
    if length(args) == 2 && (f in signed_ops || f in unsigned_ops || f in equality_ops || f in plain_ops)
        local code = Intrinsifier__binary_operator_map[][w][w][f]
        for a in args
            translate_expression(code_gen, a, w)
            f in signed_ops && signed_view(t)
            f in unsigned_ops && unsigned_view(t)
            f in equality_ops && extended_view(t)
        end
        code(code_gen)
        Intrinsifier_is_comparison(f) && return i32
        put_form(t)
        return w
    elseif length(args) == 1 && (f === I.neg_int || f === I.not_int)
        translate_expression(code_gen, args[1], w)
        Intrinsifier__unary_operator_map[][w][f](code_gen)
        put_form(t)
        return w
    elseif length(args) == 1 && (f === I.ctlz_int || f === I.cttz_int || f === I.ctpop_int)
        # a count at the type's own width (Julia's llvm.ctlz, llvm.cttz and llvm.ctpop of its iN, zero
        # defined, intrinsics.cpp:1696-:1708), promoted as LLVM's type legalizer promotes it
        translate_expression(code_gen, args[1], w)
        local count = f === I.ctlz_int ? LLVM.promote_int_res_ctlz : f === I.cttz_int ? LLVM.promote_int_res_cttz : LLVM.promote_int_res_ctpop_parity
        count(b[], w, 8 * sizeof(t))
        put_form(t)
        return w
    elseif length(args) == 1 && f === I.bswap_int && sizeof(t) == 2 && w == i32
        # a 16-bit byte swap, promoted to i32 as LLVM's type legalizer promotes it
        # (DAGTypeLegalizer::PromoteIntRes_BSWAP: the swap of the zero-extended value, shifted down by 16)
        translate_expression(code_gen, args[1], i32)
        unsigned_view(t)
        Intrinsifier__unary_operator_map[][i32][f](code_gen)
        WasmBuilder.i32_const(b[], 16)
        WasmBuilder.i32_shr_u(b[])
        put_form(t)
        return i32
    end
    return nothing
end

@parity "dart2wasm/lib/intrinsics.dart:1194 Intrinsifier.generateStaticIntrinsic" @nospecializeinfer function generate_static_intrinsic(self::Intrinsifier, ::Val{:operator}, @nospecialize(f::Core.Builtin), args::Vector{NirValue})::Union{WasmBuilder.IR.ValueType,Nothing}
    local code_gen = self.code_gen
    # whether Julia's operation on an operand of type `t`, held in the wasm number type `w`, is the
    # instruction's: the operand is as wide as `w`, or a Bool under a bitwise operation or equality
    local same_width(t::Type, w::WasmBuilder.IR.ValueType) = t isa DataType && isprimitivetype(t) &&
        (8 * sizeof(t) == 8 * WasmBuilder.byte_size(w) ||
         t === Bool && (f === Core.Intrinsics.and_int || f === Core.Intrinsics.or_int || f === Core.Intrinsics.xor_int ||
                        f === Core.Intrinsics.eq_int || f === Core.Intrinsics.ne_int))
    if length(args) == 2
        # Binary operator
        local left = args[1]
        local right = args[2]
        local left_type = type_of_exp(self, left)
        local right_type = type_of_exp(self, right)
        local code = get(get(get(Intrinsifier__binary_operator_map[], left_type, Dict{WasmBuilder.IR.ValueType,Dict{Core.IntrinsicFunction,Function}}()),
                             right_type, Dict{Core.IntrinsicFunction,Function}()), f, nothing)
        if code !== nothing && same_width(dart_type_of(self, left), left_type) && same_width(dart_type_of(self, right), right_type)
            local out_type = Intrinsifier_is_comparison(f) ? WasmBuilder.IR.NumType_i32 : left_type
            translate_expression(code_gen, left, left_type)
            translate_expression(code_gen, right, right_type)
            code(code_gen)
            return out_type
        end
    elseif length(args) == 1
        # Unary operator
        local operand = args[1]
        local operand_type = type_of_exp(self, operand)
        local code = get(get(Intrinsifier__unary_operator_map[], operand_type, Dict{Core.IntrinsicFunction,Function}()), f, nothing)
        if code !== nothing && same_width(dart_type_of(self, operand), operand_type)
            translate_expression(code_gen, operand, operand_type)
            code(code_gen)
            return operand_type
        end
    end
    return nothing
end

# dart's constructor intrinsics are dart:_wasm's own types (WasmArray, the SIMD values); no Julia
# struct is one, so no allocation is intrinsified
@parity "dart2wasm/lib/intrinsics.dart:2836 Intrinsifier.generateConstructorIntrinsic" generate_constructor_intrinsic(self::Intrinsifier, node::NirNew)::Union{WasmBuilder.IR.ValueType,Nothing} = nothing

"""
A call of a function value inlined as an intrinsic, or `nothing`. dart's are calls of dart:_wasm's
WasmFunction and of a closure's vtable entry. A Julia call of a function value is an invoke of its
method, Julia having resolved it, so no call is one.
"""
@parity "dart2wasm/lib/intrinsics.dart:2875 Intrinsifier.generateFunctionCallIntrinsic" generate_function_call_intrinsic(self::Intrinsifier, node::NirInvoke)::Union{WasmBuilder.IR.ValueType,Nothing} = nothing

# the body of a member intrinsic's function (MemberIntrinsic.fromProcedure), the runtime's port of its
# dart member; any other method's function is its body
@parity "dart2wasm/lib/intrinsics.dart:2943 Intrinsifier.generateMemberIntrinsic" function generate_member_intrinsic(self::Intrinsifier, target::Core.MethodInstance, function_type::WasmBuilder.IR.FunctionType, param_locals::Vector{WasmBuilder.IR.Local}, return_label::Union{Nothing,WasmBuilder.Label})::Bool
    local intrinsic = MemberIntrinsic_from_procedure(target)
    intrinsic === nothing && return false
    local b = self.code_gen.b[]
    # Error._throw: the object and its stack trace thrown with the program's exception tag. dart first
    # stores the stack trace in an Error's _stackTrace field where the field is null; Julia's exceptions
    # have no such field, so the object and the trace are all. Every other intrinsic's dart member has
    # no runtime port (MemberIntrinsic.fromProcedure), so none reaches here
    intrinsic === MemberIntrinsic_errorThrow ||
        reject!(Internal("dart2wasm/lib/intrinsics.dart:2943 Intrinsifier.generateMemberIntrinsic: the member intrinsic $intrinsic, whose dart member the runtime does not port"), "$target")
    local object_local = param_locals[1] # ref #Top
    local stack_trace_local = param_locals[2]
    local tag = get_dart_exception_tag(translator(self), b.module_builder)
    WasmBuilder.local_get(b, object_local)
    convert_type(translator(self), b, object_local.type, tag.type.inputs[1])
    WasmBuilder.local_get(b, stack_trace_local)
    convert_type(translator(self), b, stack_trace_local.type, tag.type.inputs[2])
    WasmBuilder.throw_(b, tag)
    return true
end

"""
    read_int_array(self, array_type; unsigned) -> ValueType

The read of a typed wasm array's element, its array and its i32 index on the stack: a packed i8 or i16
element read sign-extended or zero-extended (array.get_s or array.get_u, by `unsigned`), any other
element as it is stored (array.get). dart's readIntArray also translates the array and index operands
and widens a 32-bit result to its 64-bit int (outerExtend); a Julia element keeps its own type's width,
an 8- or 16-bit integer held in an i32 in its type's form (Translator.translateType), so the caller
pushes the operands (a Memory's data array at the reference's offset) and nothing is widened.
"""
@parity "dart2wasm/lib/intrinsics.dart:3490 Intrinsifier.readIntArray" function read_int_array(self::Intrinsifier, array_type::WasmBuilder.IR.ArrayType; unsigned::Bool)::WasmBuilder.IR.ValueType
    local b = self.code_gen.b[]
    local wasm_type = array_type.element_type[].type
    local inner_extend = wasm_type == WasmBuilder.IR.PackedType_i8 || wasm_type == WasmBuilder.IR.PackedType_i16
    if inner_extend
        unsigned ? WasmBuilder.array_get_u(b, array_type) : WasmBuilder.array_get_s(b, array_type)
    else
        WasmBuilder.array_get(b, array_type)
    end
    return WasmBuilder.unpacked(wasm_type)
end

# the memory a dart:_wasm memory intrinsic names, which no Julia call is: Julia's memory is its
# objects (WasmGC), not a linear memory a call names
@parity "dart2wasm/lib/intrinsics.dart:3536 Intrinsifier._extractMemoryFromCall" _extract_memory_from_call(self::Intrinsifier, expr::NirValue, builder::WasmBuilder.InstructionsBuilder)::WasmBuilder.IR.Memory =
    reject!(Internal("dart2wasm/lib/intrinsics.dart:3536 Intrinsifier._extractMemoryFromCall: a dart:_wasm memory access, which no Julia call is"), "Intrinsifier._extractMemoryFromCall")

# the memory, offset and alignment of a dart:_wasm memory intrinsic, which no Julia call is
@parity "dart2wasm/lib/intrinsics.dart:3549 Intrinsifier._extractMemoryOperands" _extract_memory_operands(self::Intrinsifier, call::NirInvoke, builder::WasmBuilder.InstructionsBuilder)::NamedTuple{(:memory, :offset, :align),Tuple{WasmBuilder.IR.Memory,Int,Int}} =
    reject!(Internal("dart2wasm/lib/intrinsics.dart:3549 Intrinsifier._extractMemoryOperands: a dart:_wasm memory access, which no Julia call is"), "Intrinsifier._extractMemoryOperands")

"""
An operand's value when it is an integer literal (dart's `int`, Julia's `Int64`, the NIR's literal),
else `nothing`.
"""
@parity "dart2wasm/lib/intrinsics.dart:3573 extractIntValue" extract_int_value(expr::NirValue)::Union{Int,Nothing} =
    expr isa NirConst && expr.c.val isa Int64 ? expr.c.val : nothing

"""
An operand's integers when it is a constant list of them (dart's ListConstant; Julia's literal tuple
of `Int64`s), else `nothing`.
"""
@parity "dart2wasm/lib/intrinsics.dart:3588 _extractLaneIndices" function _extract_lane_indices(expr::NirValue)::Union{Vector{Int},Nothing}
    expr isa NirConst && expr.c.val isa Tuple || return nothing
    local bytes = Int[]
    for entry in expr.c.val
        entry isa Int64 || return nothing
        push!(bytes, entry)
    end
    return bytes
end

"""An operand's value when it is a float literal (dart's `double`, Julia's `Float64`), else `nothing`."""
@parity "dart2wasm/lib/intrinsics.dart:3606 _extractDoubleValue" _extract_double_value(expr::NirValue)::Union{Float64,Nothing} =
    expr isa NirConst && expr.c.val isa Float64 ? expr.c.val : nothing
